    Gun.prototype.update = function(delta) {
        if (this.actor) this.actor.update(delta);
    };
    Gun.prototype.collectAmmo = function() {
        if (this.actor) {
            this.ammo.store = Math.min(this.ammo.storeMax, this.ammo.store + this.ammo.pickup);
            return true;
        }
        if (this.ammo.store < this.ammo.storeMax) {
            this.ammo.store = Math.min(this.ammo.storeMax, this.ammo.store + this.ammo.pickup);
            return true;
        }
        return false;
    };
    Gun.prototype.fire = function() {
        if (this.actor) {
            this.actor.fire();
            return;
        }
        var rotMat = BABYLON.Matrix.RotationYawPitchRoll(this.player.yaw, this.player.pitch, 0);
        var forwardMat = BABYLON.Matrix.Translation(0, 0, this.subClass.range);
        var dirMat = forwardMat.multiply(rotMat, forwardMat);
        var dir = dirMat.getTranslation();
        var spread = (this.player.shotSpread + this.subClass.accuracy) * .004;
        if (isNaN(spread)) {
            this.player.shotSpread = 0;
            spread = 0;
        }
        var spreadMat = BABYLON.Matrix.RotationYawPitchRoll((Math.random() - .5) * spread, (Math.random() - .5) * spread, (Math.random() - .5) * spread);
        dirMat = dirMat.multiply(spreadMat);
        var dir = dirMat.getTranslation();
        var posMat = BABYLON.Matrix.Translation(0, .1, 0);
        posMat = posMat.multiply(rotMat);
        posMat = posMat.add(BABYLON.Matrix.Translation(this.player.x, this.player.y + .3, this.player.z));
        var pos = posMat.getTranslation();
        mathSeed = Math.randomInt(0, 256);
        pos.x = Math.floor(pos.x * 300) / 300;
        pos.y = Math.floor(pos.y * 300) / 300;
        pos.z = Math.floor(pos.z * 300) / 300;
        dir.x = Math.floor(dir.x * 300) / 300;
        dir.y = Math.floor(dir.y * 300) / 300;
        dir.z = Math.floor(dir.z * 300) / 300;
        var output = new Comm.output(15, true);
        output.packInt8(CommCode.fire);
        output.packInt8(this.player.id);
        output.packFloat(pos.x);
        output.packFloat(pos.y);
        output.packFloat(pos.z);
        output.packFloat(dir.x);
        output.packFloat(dir.y);
        output.packFloat(dir.z);
        output.packInt8(mathSeed);
        sendToAll(output.buffer);
        this.fireMunitions(pos, dir);
    };
    Gun.prototype.equip = function() {
        this.player.weaponIdx = this.player.equipWeaponIdx;
        this.player.weapon = this.player.weapons[this.player.weaponIdx];
        this.player.weapon.actor.equip();
        if (this.player.id == meId) updateAmmoUi();
    };
