    "use strict";
    function MunitionsManager(scene) {
        this.bulletPool = new Pool(function() {
            return new Bullet(scene);
        }, 200);
        this.rocketPool = new Pool(function() {
            return new Rocket(scene);
        }, 20);
        this.grenadePool = new Pool(function() {
            return new Grenade(scene);
        }, 10);
    }
    MunitionsManager.prototype.update = function(delta) {
        var that = this;
        this.bulletPool.forEachActive(function(bullet) {
            bullet.update(delta);
        });
        this.rocketPool.forEachActive(function(rocket) {
            rocket.update(delta);
        });
        this.grenadePool.forEachActive(function(grenade) {
            grenade.update(delta);
        });
    };
    MunitionsManager.prototype.throwGrenade = function(player, pos, vec) {
        var grenade = this.grenadePool.retrieve();
        grenade.throw(player, pos, vec);
    };
    MunitionsManager.prototype.getMapIntersectionPoint = function(proj, res) {
        if (res && !mapMeshes[res.cell.idx].softness && res.cell && res.cell.idx) {
            var mapMesh = mapMeshes[res.cell.idx];
            var ray = new BABYLON.Ray(new BABYLON.Vector3(proj.x - proj.dx - res.x - .5, proj.y - proj.dy - res.y - .5, proj.z - proj.dz - res.z - .5), new BABYLON.Vector3(proj.dx * 2, proj.dy * 2, proj.dz * 2), 1);
            mapMesh.rotation.x = res.cell.rx;
            mapMesh.rotation.y = res.cell.ry;
            mapMesh.rotation.z = res.cell.rz;
            var pickInfo = ray.intersectsMesh(mapMesh, false);
            if (pickInfo.hit) {
                var ofs = new BABYLON.Vector3(-proj.dx, -proj.dy, -proj.dz).normalize().scale(.005);
                return {
                    x: pickInfo.pickedPoint.x + res.x + .5 + ofs.x,
                    y: pickInfo.pickedPoint.y + res.y + .5 + ofs.y,
                    z: pickInfo.pickedPoint.z + res.z + .5 + ofs.z
                };
            }
        }
        return false;
    };
