    Player.prototype.disableShield = function() {
        this.shield = 0;
        if (this.actor) {
            this.actor.bodyMesh.renderOverlay = false;
            this.actor.hands.renderOverlay = false;
        }
    };
    Player.prototype.enableShield = function() {
        this.shield = 120;
        if (this.actor) {
            this.actor.bodyMesh.renderOverlay = true;
            this.actor.hands.renderOverlay = true;
        }
    };
    Player.prototype.resetStateBuffer = function() {
        for (var i = 0; i < stateBufferSize; i++) {
            this.stateBuffer[i] = {
                delta: 0,
                yaw: this.yaw,
                pitch: this.pitch,
                fire: false,
                jump: false,
                jumping: false,
                climbing: false,
                x: this.x,
                y: this.y,
                z: this.z,
                dx: 0,
                dy: 0,
                dz: 0,
                controlKeys: 0
            };
        }
    };
    Player.prototype.moveX = function(ndx, delta) {
        var old_x = this.x;
        this.x += ndx;
        var collide = this.collidesWithMap();
        if (collide) {
            var old_y = this.y;
            this.y += Math.abs(ndx) + .01 * delta;
            if (this.collidesWithMap()) {
                this.x = old_x;
                this.dx *= .5;
                this.y = old_y;
            } else {
                this.dx *= .92;
            }
            this.lookForLadder(collide);
        }
    };
    Player.prototype.moveZ = function(ndz, delta) {
        var old_z = this.z;
        this.z += ndz;
        var collide = this.collidesWithMap();
        if (collide) {
            var old_y = this.y;
            this.y += Math.abs(ndz) + .01 * delta;
            if (this.collidesWithMap()) {
                this.z = old_z;
                this.dz *= .5;
                this.y = old_y;
            } else {
                this.dz *= .92;
            }
            this.lookForLadder(collide);
        }
    };
    Player.prototype.moveY = function(ndy, delta) {
        var old_y = this.y;
        this.y += ndy;
        if (this.collidesWithMap()) {
            if (ndy < 0) {
                if (this.actor && this.id == meId && this.lastTouchedGround == 0) {
                    this.lastTouchedGround = Date.now();
                }
                this.setJumping(false);
            }
            this.y = old_y;
            this.dy *= .5;
        } else if (this.jumping == false) {
            var old_y = this.y;
            this.y -= .2;
            if (!this.collidesWithMap()) {
                this.setJumping(true);
            } else {
                this.dy = -Math.length2(this.dx, this.dz);
            }
            this.y = old_y;
        }
    };
    Player.prototype.canJump = function() {
        if (this.actor && this.id != meId) return true;
        var canJump = !this.jumping | this.climbing;
        return canJump;
    };
    Player.prototype.jump = function() {
        if (this.climbing) {
            this.dy = .03;
            this.climbing = false;
            this.setJumping(true);
            return true;
        }
        if (this.canJump()) {
            this.dy = .063;
            this.setJumping(true);
            this.lastTouchedGround = 0;
            return true;
        }
        return false;
    };
    Player.prototype.setJumping = function(jumping) {
        this.jumping = jumping;
        this.stateBuffer[this.stateIdx].jumping = jumping;
    };
    Player.prototype.changeCharacter = function(classIdx, primaryWeaponItem, secondaryWeaponItem, shellColor, hatItem, stampItem) {
        var itemChanged = function(oldItem, newItem) {
            return oldItem && !newItem || !oldItem && newItem || oldItem !== null && newItem !== null && oldItem.id !== newItem.id;
        };
        if (classIdx !== this.charClass || primaryWeaponItem.id !== this.primaryWeaponItem.id || secondaryWeaponItem.id !== this.secondaryWeaponItem.id || shellColor !== this.shellColor || itemChanged(hatItem) || itemChanged(stampItem)) {
            this.charClass = classIdx;
            this.primaryWeaponItem = primaryWeaponItem;
            this.secondaryWeaponItem = secondaryWeaponItem;
            this.shellColor = shellColor;
            this.hatItem = hatItem;
            this.stampItem = stampItem;
            if (this.actor) {
                this.actor.setShellColor(shellColor);
                if (this.id == meId) {
                    var output = new Comm.output(7);
                    output.packInt8(CommCode.changeCharacter);
                    output.packInt8(classIdx);
                    output.packInt8(catalog.get8BitItemId(primaryWeaponItem, classIdx));
                    output.packInt8(catalog.get8BitItemId(secondaryWeaponItem, classIdx));
                    output.packInt8(shellColor);
                    output.packInt8(catalog.get8BitItemId(hatItem, classIdx));
                    output.packInt8(catalog.get8BitItemId(stampItem, classIdx));
                    ws.send(output.buffer);
                } else {
                    this.actor.wearHat(this.hatItem);
                    this.actor.applyStamp(this.stampItem);
                }
            } else {
                var output = new Comm.output(8, true);
                output.packInt8(CommCode.changeCharacter);
                output.packInt8(this.id);
                output.packInt8(classIdx);
                output.packInt8(catalog.get8BitItemId(primaryWeaponItem, classIdx));
                output.packInt8(catalog.get8BitItemId(secondaryWeaponItem, classIdx));
                output.packInt8(shellColor);
                output.packInt8(catalog.get8BitItemId(hatItem, classIdx));
                output.packInt8(catalog.get8BitItemId(stampItem, classIdx));
                sendToOthers(output.buffer, this.id);
            }
            this.changeWeaponLoadout(primaryWeaponItem, secondaryWeaponItem);
        }
    };
    Player.prototype.swapWeapon = function(idx) {
        if (this.actor && this.id != meId || this.canSwapOrReload() && idx < 2) {
            this.equipWeaponIdx = idx;
            this.releaseTrigger();
            this.swapWeaponCountdown = this.weapon.stowWeaponTime + this.weapons[idx].equipTime;
            if (!this.actor) {
                this.swapWeaponCountdown *= .9;
                this.weaponSwapsQueued--;
                var output = new Comm.output(3, true);
                output.packInt8(CommCode.swapWeapon);
                output.packInt8(this.id);
                output.packInt8(idx);
                sendToOthers(output.buffer, this.id);
            } else {
                if (this.id == meId) reticle.hide();
                this.weapon.actor.stow();
                if (this.id == meId) {
                    var output = new Comm.output(2);
                    output.packInt8(CommCode.swapWeapon);
                    output.packInt8(idx);
                    ws.send(output.buffer);
                }
            }
        }
    };
    Player.prototype.collectItem = function(kind, applyToWeaponIdx) {
        switch (kind) {
          case ItemManager.AMMO:
            if (this.weapons[applyToWeaponIdx].collectAmmo()) {
                if (this.actor) {
                    Sounds.ammo.play(this.actor.bodyMesh.absolutePosition);
                    updateAmmoUi();
                }
                return true;
            }
            return false;

          case ItemManager.GRENADE:
            if (this.grenadeCount < this.grenadeCapacity) {
                this.grenadeCount++;
                if (this.actor) {
                    Sounds.ammo.play(this.actor.bodyMesh.absolutePosition);
                    updateAmmoUi();
                }
                return true;
            }
            return false;
        }
    };
    Player.prototype.isSteady = function() {
        return !this.weapon.subClass.readySpread || this.weapon.subClass.readySpread * 5 >= this.shotSpread + this.weapon.subClass.accuracy;
    };
    Player.prototype.isAtReady = function(scoped) {
        if (this.playing && this.weapon && this.reloadCountdown <= 0 && this.swapWeaponCountdown <= 0 && this.grenadeCountdown <= 0 && (!this.actor || grenadePowerUp == false)) {
            return true;
        }
        return false;
    };
    Player.prototype.canSwapOrReload = function() {
        if (this.playing && this.weapon && this.recoilCountdown <= 0 && this.reloadCountdown <= 0 && this.swapWeaponCountdown <= 0 && this.grenadeCountdown <= 0 && this.shotsQueued <= 0 && (!this.actor || grenadePowerUp == false)) {
            return true;
        }
        return false;
    };
    Player.prototype.fire = function() {
        if (this.shield > 0) {
            this.releaseTrigger();
        } else if (this.isAtReady() && this.rofCountdown <= 0) {
            if (this.weapon.ammo.rounds > 0 && this.isSteady()) {
                if (this.actor) {
                    this.actor.fire();
                } else {
                    this.recoilCountdown *= .9;
                    this.rofCountdown *= .9;
                    this.shotsQueued--;
                }
                this.weapon.fire();
                this.weapon.ammo.rounds--;
                this.recoilCountdown = this.weapon.subClass.recoil;
                this.rofCountdown = this.weapon.subClass.rof;
                this.shotSpread += this.weapon.subClass.shotSpreadIncrement;
                if (this.actor && this.id == meId) {
                    this.shotsQueued++;
                }
                if (this.weapon.subClass.automatic == false) {
                    this.releaseTrigger();
                }
                if (this.actor && this.id == meId) updateAmmoUi();
            } else {
                if (this.weapon.actor) {
                    this.weapon.actor.dryFire();
                    this.releaseTrigger();
                }
            }
        }
    };
    Player.prototype.pullTrigger = function() {
        if (grenadePowerUp == true && me.grenadeCountdown <= 0) {
            this.cancelGrenade();
        } else if (this.isAtReady() && this.rofCountdown <= 0) {
            if (this.weapon.ammo.rounds > 0) {
                if (this.isSteady()) {
                    this.triggerPulled = true;
                    this.fire();
                } else {
                    this.weapon.actor.denyFire();
                }
            } else {
                if (this.weapon.ammo.store > 0) {
                    this.reload();
                } else {
                    this.weapon.actor.dryFire();
                }
            }
        }
    };
    Player.prototype.releaseTrigger = function() {
        this.triggerPulled = false;
    };
    Player.prototype.reload = function() {
        if (this.actor && this.id != meId) {
            this.weapon.actor.reload();
            return;
        }
        if (this.weapon.ammo.rounds == this.weapon.ammo.capacity || this.weapon.ammo.store == 0 || !this.canSwapOrReload()) {
            return;
        }
        var rounds = Math.min(Math.min(this.weapon.ammo.capacity, this.weapon.ammo.reload) - this.weapon.ammo.rounds, this.weapon.ammo.store);
        this.roundsToReload = rounds;
        if (this.actor) {
            this.weapon.actor.reload();
            this.releaseTrigger();
            var output = new Comm.output(1);
            output.packInt8(CommCode.reload);
            ws.send(output.buffer);
            this.weapon.ammo.store -= rounds;
        } else {
            var output = new Comm.output(2, true);
            output.packInt8(CommCode.reload);
            output.packInt8(this.id);
            sendToOthers(output.buffer, this.id);
            this.reloadsQueued--;
        }
        if (this.weapon.ammo.rounds == 0) {
            this.reloadCountdown = this.weapon.longReloadTime;
        } else {
            this.reloadCountdown = this.weapon.shortReloadTime;
        }
    };
    Player.prototype.reloaded = function() {
        this.weapon.ammo.rounds += this.roundsToReload;
        if (this.actor) {
            if (this.id == meId) {
                updateAmmoUi();
            }
        } else {
            this.weapon.ammo.store -= this.roundsToReload;
        }
    };
    Player.prototype.queueGrenade = function(throwPower) {
        this.grenadesQueued++;
        this.grenadeThrowPower = Math.clamp(throwPower, 0, 1);
        this.grenadeCountdown = 20;
        if (!this.actor) this.grenadeCountdown *= .9;
    };
    Player.prototype.cancelGrenade = function() {
        grenadePowerUp = false;
        me.grenadeCountdown = 30;
        if (this.id == meId) {
            document.getElementById("grenadeThrowContainer").style.visibility = "hidden";
        }
        if (this.actor) this.actor.gripBone._frozen = false;
    };
    Player.prototype.throwGrenade = function() {
        if (this.shield > 0) this.disableShield();
        if (!this.actor) {
            if (this.isAtReady()) {
                if (this.grenadeCount > 0) {
                    this.grenadeCount--;
                    this.grenadesQueued--;
                    this.grenadeCountdown = 80 * .9;
                    this.grenadeCountdown = 1;
                    var rotMat = BABYLON.Matrix.RotationYawPitchRoll(this.yaw, this.pitch, 0);
                    var forwardMat = BABYLON.Matrix.Translation(0, .1, 1);
                    var dirMat = forwardMat.multiply(rotMat);
                    var vec = dirMat.getTranslation();
                    var posMat = BABYLON.Matrix.Translation(0, -.05, .2);
                    posMat = posMat.multiply(rotMat);
                    posMat = posMat.add(BABYLON.Matrix.Translation(this.x, this.y + .3, this.z));
                    var pos = posMat.getTranslation();
                    var speed = this.grenadeThrowPower * .13 + .08;
                    vec.x *= speed;
                    vec.y *= speed;
                    vec.z *= speed;
                    pos.x = Math.floor(pos.x * 300) / 300;
                    pos.y = Math.floor(pos.y * 300) / 300;
                    pos.z = Math.floor(pos.z * 300) / 300;
                    vec.x = Math.floor(vec.x * 300) / 300;
                    vec.y = Math.floor(vec.y * 300) / 300;
                    vec.z = Math.floor(vec.z * 300) / 300;
                    var output = new Comm.output(14, true);
                    output.packInt8(CommCode.throwGrenade);
                    output.packInt8(this.id);
                    output.packFloat(pos.x);
                    output.packFloat(pos.y);
                    output.packFloat(pos.z);
                    output.packFloat(vec.x);
                    output.packFloat(vec.y);
                    output.packFloat(vec.z);
                    sendToAll(output.buffer);
                    munitionsManager.throwGrenade(this, pos, vec);
                }
            }
        } else {
            var output = new Comm.output(3);
            output.packInt8(CommCode.throwGrenade);
            output.packFloat(Math.clamp(grenadeThrowPower, 0, 1));
            ws.send(output.buffer);
            me.grenadeCountdown = 80;
            this.actor.reachForGrenade();
        }
    };
    Player.prototype.removeFromPlay = function() {
        this.playing = false;
        this.controlKeys = 0;
        this.shotSpread = 0;
        this.jumping = false;
        this.climbing = false;
        if (this.actor) {
            this.actor.removeFromPlay();
            if (this.id == meId) {
                reticle.hide();
                scope.hide();
                camera.fov = 1.25;
                grenadePowerUp = false;
                document.getElementById("grenadeThrowContainer").style.visibility = "hidden";
            }
        }
    };
    Player.prototype.scoreKill = function() {
        this.kills++;
        this.totalKills++;
        this.streak++;
        this.bestGameStreak = Math.max(this.bestGameStreak, this.streak);
        this.bestOverallStreak = Math.max(this.bestOverallStreak, this.streak);
        this.score = this.streak;
    };
    Player.prototype.die = function() {
        this.score = 0;
        this.streak = 0;
        this.deaths++;
        this.totalDeaths++;
        this.hp = 0;
        this.playing = false;
        this.removeFromPlay();
    };
    Player.prototype.respawn = function(x, y, z) {
        this.x = x;
        this.y = y;
        this.z = z;
        this.respawnQueued = false;
        this.playing = true;
        if (this.hp <= 0) {
            this.hp = 100;
            this.resetWeaponState();
        } else {
            this.resetWeaponState(true);
        }
        this.resetStateBuffer();
        if (this.actor) {
            if (this.id == meId) {
                viewingPlayerId = meId;
            }
            this.actor.mesh.position.x = x;
            this.actor.mesh.position.y = y;
            this.actor.mesh.position.z = z;
            this.actor.restoreToPlay();
            this.weapon.equip();
            if (this.id == viewingPlayerId) {
                shake = 0;
                reticle.show();
                updateAmmoUi();
            }
        }
        this.enableShield();
    };
    Player.prototype.resetWeaponState = function(dontReload) {
        this.rofCountdown = 0;
        this.shotsQueued = 0;
        this.reloadsQueued = 0;
        this.recoilCountdown = 0;
        this.reloadCountdown = 0;
        this.swapWeaponCountdown = 0;
        this.weaponSwapsQueued = 0;
        this.shotSpread = 0;
        this.equipWeaponIdx = this.weaponIdx;
        this.weapon = this.weapons[this.weaponIdx];
        this.grenadeCountdown = 0;
        this.grenadesQueued = 0;
        this.releaseTrigger();
        if (this.actor) {
            this.weapons[0].actor.gunMesh.setEnabled(false);
            this.weapons[1].actor.gunMesh.setEnabled(false);
        }
        if (!dontReload) {
            for (var i = 0; i < this.weapons.length; i++) {
                if (this.weapons[i]) {
                    this.weapons[i].ammo.rounds = this.weapons[i].ammo.capacity;
                    this.weapons[i].ammo.store = this.weapons[i].ammo.storeMax;
                }
            }
            this.grenadeCount = Math.max(this.grenadeCount, 1);
        }
    };
    Player.prototype.isDead = function() {
        return this.hp <= 0;
    };
    Player.prototype.lookForLadder = function(collide) {
        if (!collide || !collide.cell || !(this.controlKeys & CONTROL.up) || mapMeshes[collide.cell.idx].colliderType != "ladder") {
            return;
        }
        var diff = Math.abs(Math.radDifference(this.yaw, collide.cell.ry));
        if (diff > .75 && diff < 2.391) {
            return;
        }
        if (collide.cell.ry == 1 || collide.cell.ry == 3) {
            if (Math.abs(this.z - collide.z - .5) > .2) return;
        } else {
            if (Math.abs(this.x - collide.x - .5) > .2) return;
        }
        this.climbingCell.x = collide.x;
        this.climbingCell.z = collide.z;
        this.climbingCell.ry = collide.cell.ry;
        this.climbing = true;
        this.lastTouchedGround = Date.now() + 100;
        this.setJumping(false);
    };
    Player.prototype.getOccupiedCell = function() {
        if (this.x < 0 || this.y < 0 || this.z < 0 || this.x >= map.width || this.y >= map.height || this.z > map.depth) {
            return {};
        }
        var cx = Math.floor(this.x);
        var cy = Math.floor(this.y + 1e-4);
        var cz = Math.floor(this.z);
        return map.data[cx][cy][cz];
    };
    Player.prototype.collidesWithMap = function() {
        return Collider.playerCollidesWithMap(this);
    };
    "use strict";
    function Pool(constructorFn, size) {
        this.size = 0;
        this.originalSize = size;
        this.constructorFn = constructorFn;
        this.objects = [];
        this.idx = 0;
        this.numActive = 0;
        this.expand(size);
    }
    Pool.prototype.expand = function(num) {
        for (var i = 0; i < num; i++) {
            var obj = this.constructorFn();
            obj.id = i + this.size;
            obj.active = false;
            this.objects.push(obj);
        }
        this.size += num;
    };
    Pool.prototype.retrieve = function(id) {
        if (id != undefined) {
            while (id >= this.size) {
                this.expand(this.originalSize);
            }
            this.numActive++;
            this.objects[id].active = true;
            return this.objects[id];
        }
        var i = this.idx;
        do {
            i = (i + 1) % this.size;
            var obj = this.objects[i];
            if (!obj.active) {
                this.idx = i;
                this.numActive++;
                obj.active = true;
                return obj;
            }
        } while (i != this.idx);
        this.expand(this.originalSize);
        return this.retrieve();
    };
    Pool.prototype.recycle = function(obj) {
        obj.active = false;
        this.numActive--;
    };
    Pool.prototype.forEachActive = function(fn) {
        for (var i = 0; i < this.size; i++) {
            var obj = this.objects[i];
            if (obj.active === true) {
                fn(obj, i);
            }
        }
    };
