    function loadMeshes(scene, meshNames, onMeshLoaded, onComplete) {
        var meshCount = meshNames.length;
        var that = this;
        var mat = scene.getMaterialByName("standard");
        var numEggs = 0;
        var numHands = 0;
        for (var idx = 0; idx < meshCount; idx++) {
            var rootUrl = "models/";
            var path = meshNames[idx] + ".babylon";
            if (typeof window === "undefined") {
                var data = fs.readFileSync(path, "utf8");
                data = data.replace(/\r?\n|\r/g, "");
                path = "data:" + data;
                rootUrl = "";
            }
            BABYLON.SceneLoader.ImportMesh("", rootUrl, path, scene, function(meshes, partcileSystems, skeletons) {
                try {
                    for (var m = 0; m < meshes.length; m++) {
                        var mesh = meshes[m];
                        if (mesh.name == "egg") numEggs++;
                        if (mesh.name == "hands") numHands++;
                        if (!duplicateWarningIssued && (numEggs > 1 || numHands > 1)) {
                            duplicateWarningIssued = true;
                            alert("Duplicate egg and/or hand models detected.\n\nOpen the weapon models in Blender and make sure egg/hands layers are turned off, then re-export.");
                        }
                        if (mesh.setMaterial) mesh.setMaterial(mat);
                        mesh.setEnabled(false);
                        mesh.isPickable = false;
                        if (onMeshLoaded) onMeshLoaded(mesh);
                    }
                    meshCount--;
                    if (meshCount == 0 && onComplete) {
                        onComplete.call(that);
                    }
                } catch (e) {
                    console.log(e);
                }
            });
        }
    }
    function buildMapData(errorFunc) {
        map = {
            width: minMap.width,
            height: minMap.height + 1,
            depth: minMap.depth,
            surfaceArea: minMap.surfaceArea
        };
        map.data = make3DArray(map.width, map.height, map.depth);
        var meshIndex = {};
        for (var i = 1; i < mapMeshes.length; i++) {
            var mesh = mapMeshes[i];
            meshIndex[mesh.name] = i;
        }
        var meshesNotFound = {};
        if (typeof window === "undefined") spawnPoints = [ [], [], [] ];
        Object.keys(minMap.data).forEach(function(meshName) {
            var meshData = minMap.data[meshName];
            var meshIdx = meshIndex[meshName];
            var mesh = mapMeshes[meshIdx];
            if (!meshIdx) {
                meshesNotFound[meshName] = true;
            } else {
                var fields = meshName.split(".");
                mesh.theme = fields[0];
                mesh.name = fields[1];
                mesh.colliderType = fields[2];
                mesh.softness = fields[3];
                if (typeof window === "undefined") {
                    if (mesh.theme == "SPECIAL") {
                        if (mesh.name.startsWith("spawn")) {
                            Object.values(meshData).forEach(function(cell) {
                                spawnPoints[0].push({
                                    x: cell.x,
                                    y: cell.y,
                                    z: cell.z
                                });
                                if (mesh.name == "spawn-blue") {
                                    spawnPoints[Team.blue].push({
                                        x: cell.x,
                                        y: cell.y,
                                        z: cell.z
                                    });
                                } else {
                                    spawnPoints[Team.red].push({
                                        x: cell.x,
                                        y: cell.y,
                                        z: cell.z
                                    });
                                }
                            });
                            return;
                        } else if (mesh.name == "spatula") {
                            Object.values(meshData).forEach(function(cell) {
                                spatulaSpawnPoints.push({
                                    x: cell.x + .5,
                                    y: cell.y + .1,
                                    z: cell.z + .5
                                });
                            });
                            return;
                        }
                    }
                }
                var colliderMesh;
                var colliderPrecise;
                var colliderChildren;
                switch (mesh.colliderType) {
                  case "full":
                    colliderMesh = Collider.fullCollisionMesh;
                    colliderPrecise = false;
                    colliderChildren = false;
                    break;

                  case "wedge":
                    colliderMesh = Collider.wedgeCollisionMesh;
                    colliderPrecise = true;
                    colliderChildren = false;
                    break;

                  case "iwedge":
                    colliderMesh = Collider.iwedgeCollisionMesh;
                    colliderPrecise = true;
                    colliderChildren = false;
                    break;

                  case "ladder":
                    colliderMesh = mesh.colliderMesh;
                    colliderPrecise = false;
                    colliderChildren = false;
                    break;

                  case "aabb":
                    colliderMesh = mesh.colliderMesh;
                    colliderPrecise = false;
                    colliderChildren = true;
                    break;

                  case "obb":
                    colliderMesh = mesh.colliderMesh;
                    colliderPrecise = true;
                    colliderChildren = true;
                    break;
                }
                Object.values(meshData).forEach(function(cell) {
                    var rx = cell.rx * Math.PI90 || 0;
                    var ry = cell.ry * Math.PI90 || 0;
                    var rz = cell.rz * Math.PI90 || 0;
                    map.data[cell.x][cell.y][cell.z] = {
                        item: undefined,
                        mesh: mesh,
                        idx: meshIdx,
                        colliderMesh: colliderMesh,
                        colliderPrecise: colliderPrecise,
                        colliderChildren: colliderChildren,
                        colliderMatrix: BABYLON.Matrix.RotationYawPitchRoll(-ry, -rx, -rz),
                        rx: rx,
                        ry: ry,
                        rz: rz
                    };
                });
            }
        });
        var str = "";
        Object.keys(meshesNotFound).forEach(function(name) {
            str += name + "\n";
        });
        if (str != "") errorFunc(str);
        return meshIndex;
    }
    function make3DArray(width, height, depth, initVal) {
        var arr = Array(width);
        for (var x = 0; x < width; x++) {
            arr[x] = Array(height);
            for (var y = 0; y < height; y++) {
                arr[x][y] = Array(depth);
                for (var z = 0; z < depth; z++) {
                    arr[x][y][z] = initVal || {};
                }
            }
        }
        return arr;
    }
    "use strict";
    function Rocket(scene) {
        this.scene = scene;
        this.x = 0;
        this.y = 0;
        this.z = 0;
        this.dx = 0;
        this.dy = 0;
        this.dz = 0;
        this.active = false;
        this.player = null;
        this.damage = 150;
        if (typeof RocketActor != "undefined") {
            this.actor = new RocketActor(this);
            this.end = new BABYLON.Vector3();
        }
    }
    Rocket.origin = new BABYLON.Vector3();
    Rocket.direction = new BABYLON.Vector3();
    Rocket.prototype.remove = function() {
        munitionsManager.rocketPool.recycle(this);
        if (this.actor) this.actor.remove();
    };
    Rocket.prototype.update = function(delta) {
        Rocket.origin.set(this.x, this.y, this.z);
        Rocket.direction.set(this.dx, this.dy, this.dz);
        if (Collider.rayCollidesWithPlayer(Rocket.origin, Rocket.direction, this)) {
            return;
        }
        if (this.range <= 0) {
            this.x -= this.dx;
            this.y -= this.dy;
            this.z -= this.dz;
            if (this.minRange <= 0) {
                this.explode();
            } else {
                this.poof();
            }
            return;
        }
        this.x += this.dx * delta;
        this.y += this.dy * delta;
        this.z += this.dz * delta;
        var travel = this.velocity * delta;
        this.range -= travel;
        this.minRange -= travel;
        if (this.actor) this.actor.update();
    };
    Rocket.fire = function(player, pos, dir, weaponClass) {
        var rocket = munitionsManager.rocketPool.retrieve();
        rocket.fireThis(player, pos, dir, weaponClass);
    };
    Rocket.prototype.fireThis = function(player, pos, dir, weaponClass) {
        this.radius = weaponClass.radius;
        this.player = player;
        this.x = pos.x;
        this.y = pos.y;
        this.z = pos.z;
        this.weaponClass = weaponClass;
        var v = dir.clone().normalize();
        this.dx = v.x * weaponClass.velocity;
        this.dy = v.y * weaponClass.velocity;
        this.dz = v.z * weaponClass.velocity;
        this.damage = weaponClass.damage;
        this.active = true;
        this.range = weaponClass.range;
        this.minRange = weaponClass.minRange;
        this.velocity = weaponClass.velocity;
        var res = Collider.rayCollidesWithMap(pos, dir, Collider.projectileCollidesWithCell);
        if (res) {
            if (this.actor) this.end.copyFrom(res.pick.pickedPoint);
            this.range = BABYLON.Vector3.Distance(pos, res.pick.pickedPoint);
        }
        if (this.actor) this.actor.fire();
    };
    Rocket.prototype.explode = function() {
        if (this.actor) {
            addExplosion(this.x, this.y, this.z, this.damage, this.radius);
            Rocket.origin.set(this.x, this.y, this.z);
            Sounds.rpegg.explode.play(Rocket.origin);
        } else {
            checkExplosionCollisions(this);
        }
        this.remove();
    };
    Rocket.prototype.poof = function() {
        if (this.actor) {
            Rocket.origin.set(this.x, this.y, this.z);
            Sounds.rpegg.poof.play(Rocket.origin);
            var animLength = 10;
            var size = .4;
            for (var i = 0; i < 10; i++) {
                var dx = Math.random() * .2 - .1;
                var dy = Math.random() * .2 - .1;
                var dz = Math.random() * .2 - .1;
                addExplosionSprite(explosionSmokeManager, animLength, this.x, this.y, this.z, dx, dy, dz, size, false);
            }
        }
        this.remove();
    };
    Rocket.prototype.collidesWithPlayer = function(player) {
        if (this.minRange <= 0) {
            if (!this.actor) {
                hitPlayer(player, this.player, 255, tv1.x, tv1.z);
            }
            this.explode();
        } else {
            if (!this.actor) {
                hitPlayer(player, this.player, 10, tv1.x, tv1.z);
            }
            this.poof();
        }
    };
    "use strict";
    function Spatula(scene, p) {
        this.scene = scene;
        this.x = p.x;
        this.y = p.y;
        this.z = p.z;
        this.dy = 0;
        this.controlledBy = 255;
        this.controlledByTeam = 255;
        this.lastControlTeam = 255;
        if (typeof SpatulaActor != "undefined") this.actor = new SpatulaActor(this);
    }
    Spatula.prototype.capture = function(player) {
        if (this.actor && me.id == player.id) {
            var el = document.getElementById("spatulaPlayer");
            el.className = "capture";
        }
        if (player.team != this.lastControlTeam) {
            teamScore[player.team] = 0;
        }
        this.controlledBy = player.id;
        this.controlledByTeam = player.team;
        this.lastControlTeam = player.team;
        if (!this.actor) {
            for (var i = 0; i < playerLimit; i++) {
                var p = players[i];
                if (p) {
                    if (p.team == player.team) {
                        p.canTakeSpatulaBonus = true;
                    }
                }
            }
            sendSpatulaState();
        } else {
            Sounds.spatula.capture.play();
            var el = document.getElementById("teamScoreNum" + player.team);
            el.innerText = teamScore[player.team];
        }
    };
    Spatula.prototype.drop = function() {
        if (this.actor && me.id == this.controlledBy) {
            var el = document.getElementById("spatulaPlayer");
            el.className = "drop";
        }
        var player = players[this.controlledBy];
        this.controlledBy = 255;
        this.controlledByTeam = 255;
        this.x = player.x;
        this.y = player.y;
        this.z = player.z;
        this.dy = player.dy + .05;
        if (!this.actor) {
            for (var i = 0; i < playerLimit; i++) {
                var player = players[i];
                if (player) {
                    player.canTakeSpatulaBonus = false;
                }
            }
            sendSpatulaState();
        } else {
            this.actor.drop();
        }
    };
    Spatula.prototype.update = function(delta) {
        if (this.controlledBy == 255) {
            var pdy = this.dy;
            this.dy -= .003 * delta;
            var ndy = .5 * (this.dy + pdy) * delta;
            var oldY = this.y;
            this.y += ndy;
            if (this.collidesWithMap()) {
                this.y = oldY;
                this.dy *= -.5;
            }
            if (!this.actor) {
                for (var i = 0; i < playerLimit; i++) {
                    var player = players[i];
                    if (player && player.playing && Math.abs(this.x - player.x) < .35 && Math.abs(this.y - player.y) < .35 && Math.abs(this.z - player.z) < .35) {
                        this.capture(player);
                        break;
                    }
                }
            }
        } else {
            var player = players[this.controlledBy];
            if (player) {
                this.x = player.x - Math.sin(player.yaw) * .3;
                this.y = player.y;
                this.z = player.z - Math.cos(player.yaw) * .3;
            }
        }
        if (this.actor) {
            this.actor.update(delta);
        }
    };
    Spatula.v1 = new BABYLON.Vector3();
    Spatula.prototype.collidesWithMap = function() {
        Spatula.v1.set(this.x, this.y, this.z);
        return Collider.meshCollidesWithMap(Collider.playerCollisionMesh, Spatula.v1);
    };
    function isBadWord(word) {
        word = " " + word + " ";
        var str = word.toLowerCase().replace(/[^a-zA-Z0-9|!\|@|$|;|¡]/g, "").replace(/6|g/g, "9").replace(/b/g, "6").replace(/\||l|i|1|;|¡/g, "!").replace(/e/g, "3").replace(/a|@/g, "4").replace(/o/g, "0").replace(/s|\$/g, "5").replace(/t/g, "7").replace(/z/g, "2").replace(/7h3|my|y0ur|7h3!r|h!5|h3r/g, "");
        var i1 = str.search(/( 94y | cum| 455 )/);
        str.replace(/ /g, "");
        var reg = /(4fr!c4n|kn336r0|5ch00!5h007|73rr0r!5t|卐|卍|qu33r|d!ck|w4nk|p!55|7357!c|735735|64!!5|nu75|nu72|j3w|k!k3|r374r|4u7!5|d0wn55|6006|8d|p0rn|5w4!!0w|347m3|347my|d!k|0r4!|5p0093|fuk|j!2|5u!c!d|m4573r6|5p0063|5p3rm|p3nu5|pu55y|6u7753x|fux|6u77h0!3|4n4!|4nu5|k!!!b!4ck5|murd3rb!4ck5|h!7!3r|w3764ck|49!n4|94y|455h0!3|5uck|j3w|5p!c|ch!nk|n!994|n!993|n!663|n!994|n!664|5h!7|6!7ch|fuck|cun7|kkk|wh0r3|f49|7w47|p3n!|r4p3w0m|r4p39!r|r4p!57|r4p3r|r4p!n|c0ck|7!75|900k|d!ckh34d)/;
        var i2 = str.search(reg);
        str.replace(/(.)(?=\1)/g, "");
        var i3 = str.search(reg);
        return i1 > -1 || i2 > -1 || i3 > -1;
    }
