    var smokeColors = [ {
        pos: 0,
        color: new BABYLON.Color4(.3, .3, .3, 1)
    }, {
        pos: 1,
        color: new BABYLON.Color4(.7, .7, .7, 0)
    } ];
    var bulletHitColors = [ {
        pos: 0,
        color: new BABYLON.Color4(1, 1, 1, 1)
    }, {
        pos: .2,
        color: new BABYLON.Color4(.7, .7, .7, .7)
    }, {
        pos: 1,
        color: new BABYLON.Color4(.7, .7, .7, 0)
    } ];
    function lerp(colors, p, ref) {
        for (var i = colors.length - 2; i >= 0; i--) {
            if (p >= colors[i].pos) {
                BABYLON.Color4.LerpToRef(colors[i].color, colors[i + 1].color, (p - colors[i].pos) * (1 / (colors[i + 1].pos - colors[i].pos)), ref);
                return;
            }
        }
    }
    function shellFragBurst(player, count, theSize, theAnimLength) {
        for (var i = 0; i < count; i++) {
            var animLength = Math.random() * theAnimLength + theAnimLength * .5;
            var size = i / (count * .5) * theSize + theSize * .5;
            var se = .08 / (size + 1);
            var dx = (Math.random() * 2 - 1) * se;
            var dy = (Math.random() * 2 - .5) * se;
            var dz = (Math.random() * 2 - 1) * se;
            var s = shellFragManager.getSprite();
            s.animLength = animLength;
            s.easing = Ease.inQuad;
            s.position.x = player.actor.mesh.position.x;
            s.position.y = player.actor.mesh.position.y + .3;
            s.position.z = player.actor.mesh.position.z;
            s.startSize = size;
            s.endSize = 0;
            s.gravity = .003;
            s.dx = dx;
            s.dy = dy;
            s.dz = dz;
            s.angle = Math.random() * Math.PI2;
            s.rotate = Math.random() * .2 - .1;
            s.collide = true;
            s.color.r = player.actor.bodyMesh.colorMult.r;
            s.color.g = player.actor.bodyMesh.colorMult.g;
            s.color.b = player.actor.bodyMesh.colorMult.b;
        }
    }
    function yolkBurst(player) {
        var count = 10;
        var theSize = .2;
        for (var i = 0; i < count; i++) {
            var animLength = Math.random() * 80 + 80;
            var size = i / (count * .5) * theSize + theSize;
            var se = .05 / (size + 1);
            var dx = (Math.random() * 2 - 1) * se;
            var dy = (Math.random() * 2 - .25) * se * 1.5;
            var dz = (Math.random() * 2 - 1) * se;
            var s = yolkManager.getSprite();
            s.animLength = animLength;
            s.easing = Ease.inQuad;
            s.position.x = player.actor.mesh.position.x;
            s.position.y = player.actor.mesh.position.y + .3;
            s.position.z = player.actor.mesh.position.z;
            s.startSize = size;
            s.endSize = 0;
            s.gravity = .005;
            s.dx = dx;
            s.dy = dy;
            s.dz = dz;
            s.slow = .9;
            s.angle = Math.random() * Math.PI2;
            s.rotate = Math.random() * .2 - .1;
            s.collide = true;
        }
    }
    function updateParticles(manager, delta) {
        for (var i = 0; i < manager.sprites.length; i++) {
            var s = manager.sprites[i];
            if (s.isVisible) {
                var anim = s.easing(s.anim);
                if (s.endSize >= 0) {
                    s.size = s.startSize + anim * (s.endSize - s.startSize);
                }
                if (s.animColors) {
                    lerp(s.animColors, anim, s.color);
                }
                if (!s.stopped) {
                    s.position.x += s.dx;
                    s.position.y += s.dy + s.float;
                    s.position.z += s.dz;
                    if (s.rotate) s.angle += s.rotate;
                    var res = false;
                    if (s.collide) {
                        tv1.set(s.position.x, s.position.y, s.position.z);
                        res = Collider.pointCollidesWithMap(tv1, true);
                    }
                    if (res) {
                        s.stopped = true;
                        s.position.x -= s.dx;
                        s.position.y -= s.dy;
                        s.position.z -= s.dz;
                    } else if (s.gravity) {
                        s.dy -= s.gravity;
                    }
                    if (s.slow) {
                        s.dx *= s.slow;
                        s.dy *= s.slow;
                        s.dz *= s.slow;
                    }
                }
                s.anim += delta / s.animLength;
                if (s.anim >= 1) s.isVisible = false;
            }
        }
    }
    function onLoadingComplete() {
        console.log("onLoadingComplete");
        Collider.init(gameScene);
        buildMap(onMapComplete);
    }
    function onMapComplete() {
        document.getElementById("serverAndMapInfo").innerHTML = "Map: " + minMap.name + "<br>" + "Server: " + servers[selectedServer].name;
        try {
            scope = new Scope();
            hitIndicator = new HitIndicator();
            reticle = new Reticle();
            gameScene.getMeshByName("muzzleFlash").material = gameScene.getMaterialByName("muzzleFlash");
            gameScene.getMeshByName("bullet").material = gameScene.getMaterialByName("bullet");
            gameScene.getMeshByName("rocket").material = gameScene.getMaterialByName("standardInstanced");
            gameScene.getMeshByName("grenade").material = gameScene.getMaterialByName("emissive");
            gameScene.getMeshByName("ammo").material = gameScene.getMaterialByName("standardInstanced");
            gameScene.getMeshByName("grenadeItem").material = gameScene.getMaterialByName("standardInstanced");
            gameScene.getMeshByName("spatula").material = gameScene.getMaterialByName("emissive");
            munitionsManager = new MunitionsManager(gameScene);
            itemManager = new ItemManager();
            bulletHoleManager = createParticleManager("particles.png", 50, 0, 0, gameScene);
            bulletHoleManager.fogEnabled = true;
            bulletHoleManager.addHole = function(f, x, y, z) {
                var s = this.getSprite();
                s.position.x = x;
                s.position.y = y;
                s.position.z = z;
                s.angle = Math.random() * 6.282;
                s.cellIndex = f;
                s.startSize = .03;
            };
            explosionSmokeManager = createParticleManager("particles.png", 300, 1, 1, gameScene);
            explosionSmokeManager.fogEnabled = true;
            explosionSmokeManager.noAlphaTest = true;
            explosionFireManager = createParticleManager("particles.png", 300, 1, 1, gameScene);
            explosionFireManager.fogEnabled = true;
            explosionFireManager.blendMode = BABYLON.Engine.ALPHA_ADD;
            shellFragManager = createParticleManager("particles.png", 400, 3, 6, gameScene);
            shellFragManager.fogEnabled = true;
            yolkManager = createParticleManager("particles.png", 100, 2, 2, gameScene);
            yolkManager.fogEnabled = true;
            if (playOffline) {
                meId = 0;
                var playerData = {
                    id: 0,
                    uniqueId: 0,
                    name: "Test",
                    charClass: 0,
                    team: 0,
                    primaryWeaponItem: playerAccount.getPrimaryWeapon(),
                    secondaryWeaponItem: playerAccount.getSecondaryWeapon(),
                    shellColor: 0,
                    hatItem: null,
                    stampItem: null,
                    score: 0,
                    kills: 0,
                    deaths: 0,
                    streak: 0,
                    totalKills: 0,
                    totalDeaths: 0,
                    bestGameStreak: 0,
                    bestOverallStreak: 0,
                    x: mapTest.x + .5,
                    y: mapTest.y - .32,
                    z: mapTest.z + .5,
                    dx: 0,
                    dy: 0,
                    dz: 0,
                    frame: 0,
                    pitch: mapTest.pitch,
                    yaw: mapTest.yaw,
                    shield: 0,
                    hp: 0,
                    playing: false,
                    weaponIdx: 0,
                    controlKeys: 0,
                    randomSeed: 0,
                    upgradeProductId: playerAccount.upgradeProductId !== undefined && playerAccount.upgradeProductId !== null ? playerAccount.upgradeProductId : 0
                };
                addPlayer(playerData);
                players[meId].hp = 100;
                doFirstPersonCamera();
                startRendering();
                addCanvasListeners();
            } else {
                mapOverview = true;
                setUpSocket();
                var output = new Comm.output(1);
                output.packInt8(CommCode.clientReady);
                ws.send(output.buffer);
                var output = new Comm.output(1);
                output.packInt8(CommCode.ping);
                pingStartTime = Date.now();
                ws.send(output.buffer);
                setTimeout(sendOneSignalTagsForGameplay, 3e4);
            }
        } catch (e) {
            console.log(e);
        }
    }
    function doMapOverviewCamera() {
        camera.parent = null;
        camera.position = new BABYLON.Vector3(0, map.height + 1, 0);
        camera.lockedTarget = null;
        camera.setTarget(new BABYLON.Vector3(map.width / 2, map.height / 4, map.depth / 2));
        mapOverview = true;
    }
    function doFirstPersonCamera(player) {
        camera.position = BABYLON.Vector3.Zero();
        camera.rotation = BABYLON.Vector3.Zero();
        camera.rotationQuaternion = BABYLON.Quaternion.Zero();
        if (player) {
            camera.parent = player.actor.eye;
        } else {
            camera.parent = me.actor.eye;
        }
        camera.lockedTarget = null;
        mapOverview = false;
    }
    function startRendering() {
        hideDarkOverlay();
        showGameDom();
        resize();
        captureKeys();
        if (mapOverview) doMapOverviewCamera();
        gameScene.registerBeforeRender(function() {
            update();
            if (me) {
                shadowLight.position.x = viewingPlayer.x;
                shadowLight.position.y = viewingPlayer.y + 2;
                shadowLight.position.z = viewingPlayer.z;
            }
        });
        engine.runRenderLoop(function() {
            gameScene.render();
        });
    }
    var killDisplayTimeout;
    var chatParser = document.createElement("DIV");
    var prevCmd = [];
    function setUpSocket() {
        ws.onmessage = function(e) {
            var input = new Comm.input(e.data);
            var len;
            while (len = input.isMoreDataAvailable()) {
                var cmd = input.unPackInt8U();
                switch (cmd) {
                  case CommCode.pause:
                    var playerId = input.unPackInt8U();
                    var player = players[playerId];
                    if (player) player.removeFromPlay();
                    break;

                  case CommCode.clientReady:
                    console.log("CommCode.clientReady received");
                    respawnTime = -1;
                    openGameMenu();
                    startRendering();
                    if (autoInvite) inviteFriends();
                    break;

                  case CommCode.spatula:
                    var p = {
                        x: input.unPackFloat(),
                        y: input.unPackFloat(),
                        z: input.unPackFloat()
                    };
                    var controlledBy = input.unPackInt8U();
                    var controlledByTeam = input.unPackInt8U();
                    if (!spatula) {
                        spatula = new Spatula(gameScene, p);
                        spatula.controlledBy = controlledBy;
                        spatula.controlledByTeam = controlledByTeam;
                    } else {
                        if (spatula.controlledBy != controlledBy) {
                            var teamLabels = [ "", '<h1 class="blueTeam">' + getLocText("ui_game_blue") + "</h1>", '<h1 class="redTeam">' + getLocText("ui_game_red") + "</h1>" ];
                            if (controlledBy == 255) {
                                if (me.playing) {
                                    var el = document.getElementById("gameMessage");
                                    el.innerHTML = teamLabels[spatula.controlledByTeam];
                                    el.innerHTML += "<p>DROPPED<br>the spatula!</p>";
                                    el.style.display = "block";
                                    setTimeout(function() {
                                        document.getElementById("gameMessage").style.display = "none";
                                    }, 3e3);
                                }
                                spatula.drop(p);
                            } else {
                                if (me.playing) {
                                    var el = document.getElementById("gameMessage");
                                    el.innerHTML = teamLabels[controlledByTeam];
                                    el.innerHTML += "<p>CAPTURED<br>the spatula!</p>";
                                    el.style.display = "block";
                                    setTimeout(function() {
                                        document.getElementById("gameMessage").style.display = "none";
                                    }, 3e3);
                                }
                                spatula.capture(players[controlledBy]);
                            }
                        }
                    }
                    updateTeamUI();
                    break;

                  case CommCode.addPlayer:
                    var id = input.unPackInt8U();
                    var uniqueId = input.unPackInt16U();
                    var name = input.unPackString();
                    var charClass = input.unPackInt8U();
                    if (id > 17) {
                        debugArray.push("playerId out of bounds: " + id + ", " + name);
                    }
                    var playerData = {
                        id: id,
                        uniqueId: uniqueId,
                        name: name,
                        charClass: charClass,
                        team: input.unPackInt8U(),
                        primaryWeaponItem: catalog.findItemBy8BitItemId(ItemType.Primary, charClass, input.unPackInt8U()),
                        secondaryWeaponItem: catalog.findItemBy8BitItemId(ItemType.Secondary, charClass, input.unPackInt8U()),
                        shellColor: input.unPackInt8U(),
                        hatItem: catalog.findItemBy8BitItemId(ItemType.Hat, charClass, input.unPackInt8U()),
                        stampItem: catalog.findItemBy8BitItemId(ItemType.Stamp, charClass, input.unPackInt8U()),
                        x: input.unPackFloat(),
                        y: input.unPackFloat(),
                        z: input.unPackFloat(),
                        dx: input.unPackFloat(),
                        dy: input.unPackFloat(),
                        dz: input.unPackFloat(),
                        yaw: input.unPackRadU(),
                        pitch: input.unPackRad(),
                        score: input.unPackInt32U(),
                        kills: input.unPackInt16U(),
                        deaths: input.unPackInt16U(),
                        streak: input.unPackInt16U(),
                        totalKills: input.unPackInt32U(),
                        totalDeaths: input.unPackInt32U(),
                        bestGameStreak: input.unPackInt16U(),
                        bestOverallStreak: input.unPackInt16U(),
                        shield: input.unPackInt8U(),
                        hp: input.unPackInt8U(),
                        playing: input.unPackInt8U(),
                        weaponIdx: input.unPackInt8U(),
                        controlKeys: input.unPackInt8U(),
                        randomSeed: input.unPackInt16U(),
                        upgradeProductId: input.unPackInt8U()
                    };
                    if (!players[playerData.id]) {
                        if (meId == playerData.id) {} else {
                            playerData.name = playerData.name.replace(/<|>/g, "");
                            if (playerData.name.length == 0) {
                                playerData.name = "Anonymous";
                            } else {
                                playerData.name = fixStringWidth(playerData.name);
                                if (isBadWord(playerData.name)) {
                                    playerData.name = randomName();
                                }
                            }
                        }
                        addPlayer(playerData);
                    }
                    break;

                  case CommCode.removePlayer:
                    var playerId = input.unPackInt8U();
                    removePlayer(playerId);
                    break;

                  case CommCode.spawnItem:
                    var id = input.unPackInt16U();
                    var kind = input.unPackInt8U();
                    var x = input.unPackFloat();
                    var y = input.unPackFloat();
                    var z = input.unPackFloat();
                    itemManager.spawnItem(id, kind, x, y, z);
                    break;

                  case CommCode.collectItem:
                    var playerId = input.unPackInt8U();
                    var kind = input.unPackInt8U();
                    var applyToWeaponIdx = input.unPackInt8U();
                    var id = input.unPackInt16U();
                    itemManager.collectItem(kind, id);
                    if (playerId == meId) {
                        me.collectItem(kind, applyToWeaponIdx);
                    }
                    break;

                  case CommCode.die:
                    var killedId = input.unPackInt8U();
                    var byId = input.unPackInt8U();
                    var rs = input.unPackInt8U();
                    var killedPlayer = players[killedId];
                    var byPlayer = players[byId];
                    var killedPlayerName;
                    if (killedPlayer) {
                        if (spatula) {
                            var otherTeam = killedPlayer.team == 1 ? 2 : 1;
                            if (spatula.controlledByTeam == otherTeam) {
                                teamScore[otherTeam]++;
                                updateTeamUI();
                            }
                        }
                        killedPlayerName = killedPlayer.name;
                        var pos = new BABYLON.Vector3(killedPlayer.x, killedPlayer.y + .32, killedPlayer.z);
                        Sounds.shellBurst.play(pos);
                        var soundIdx = Math.randomInt(0, Sounds.death.length);
                        Sounds.death[soundIdx].setPosition(pos);
                        Sounds.death[soundIdx].play();
                        shellFragBurst(killedPlayer, 80, .2, 40);
                        yolkBurst(killedPlayer);
                        killedPlayer.die();
                        killedPlayer.actor.mesh.position.x = killedPlayer.x;
                        killedPlayer.actor.mesh.position.y = killedPlayer.y;
                        killedPlayer.actor.mesh.position.z = killedPlayer.z;
                    } else {
                        killedPlayerName = "N/A";
                    }
                    var byPlayerName;
                    if (byPlayer) {
                        byPlayerName = byPlayer.name;
                        if (!byPlayer.isDead()) {
                            byPlayer.scoreKill();
                            if (byId == meId) {
                                var el = document.getElementById("bestStreak");
                                el.innerText = byPlayer.bestOverallStreak;
                            }
                            if (byId == meId) {
                                kills++;
                                bestOverallStreak = Math.max(bestOverallStreak, byPlayer.streak);
                            }
                        }
                    } else {
                        byPlayerName = "N/A";
                    }
                    if (killedId != meId) {
                        if (byId == meId) {
                            var killBox = document.getElementById("killBox");
                            killBox.style.display = "block";
                            document.getElementById("KILLED_NAME").innerText = killedPlayerName;
                            var streakEl = document.getElementById("KILL_STREAK");
                            if (me.streak > 1) {
                                streakEl.innerText = me.streak + "-KILL STREAK";
                            } else {
                                streakEl.innerText = "";
                            }
                            var scale = 1.5;
                            var scaleInterval = interval.set(function() {
                                killBox.style.transform = "scale(" + scale + "," + scale + ")";
                                scale -= .05;
                                if (scale <= 1) {
                                    scale = 1;
                                    interval.clear(scaleInterval);
                                }
                            }, 33);
                            killDisplayTimeout = timeout.set(function() {
                                if (inGame) killBox.style.display = "none";
                            }, 4e3);
                        }
                    } else {
                        camera.parent = null;
                        camera.position = new BABYLON.Vector3(viewingPlayer.actor.mesh.position.x, viewingPlayer.actor.mesh.position.y + .2, viewingPlayer.actor.mesh.position.z);
                        if (byPlayer) {
                            camera.lockedTarget = byPlayer.actor.bodyMesh;
                        }
                        document.getElementById("KILLED_BY_NAME").innerText = byPlayerName;
                        var deathBox = document.getElementById("deathBox");
                        deathBox.style.display = "block";
                        var scale = 2;
                        var scaleInterval = interval.set(function() {
                            deathBox.style.transform = "scale(" + scale + "," + scale + ")";
                            scale -= .05;
                            if (scale <= 1 && inGame) {
                                interval.clear(scaleInterval);
                                scale = 1;
                            }
                        }, 33);
                        deaths++;
                        setRespawnTime(rs);
                        removeCanvasListeners();
                        timeout.set(function() {
                            if (inGame) {
                                deathBox.style.display = "none";
                                if (viewingPlayerId == meId) openGameMenu();
                            }
                        }, 3e3);
                    }
                    if (byPlayer && killedPlayer) {
                        addKillText(byPlayer, killedPlayer);
                    }
                    rebuildPlayerList();
                    break;

                  case CommCode.chat:
                    var playerId = input.unPackInt8U();
                    var text = input.unPackString();
                    var player = players[playerId];
                    if (!player.muted) {
                        chatParser.innerHTML = text;
                        text = chatParser.textContent.trim();
                        if (player && text.length > 0 && !isBadWord(text) && text.indexOf("<") < 0) {
                            addChat(text, player);
                        }
                    }
                    break;

                  case CommCode.jump:
                    var id = input.unPackInt8U();
                    var player = players[id];
                    if (!player) break;
                    player.jump();
                    break;

                  case CommCode.sync:
                    var id = input.unPackInt8U();
                    var stateIdx = input.unPackInt8U();
                    var x = input.unPackFloat();
                    var y = input.unPackFloat();
                    var z = input.unPackFloat();
                    var climbing = input.unPackInt8U();
                    var player = players[id];
                    if (!player) {
                        for (var i = 0; i < FramesBetweenSyncs; i++) {
                            input.unPackInt8U();
                            input.unPackRadU();
                            input.unPackRad();
                        }
                        break;
                    }
                    var oldx = player.x;
                    var oldy = player.y;
                    var oldz = player.z;
                    var olddx = player.dx;
                    var olddy = player.dy;
                    var olddz = player.dz;
                    var oldYaw = player.yaw;
                    var oldPitch = player.pitch;
                    var wasJumping = player.jumping;
                    var wasClimbing = player.climbing;
                    if (id == meId) {
                        for (var i = 0; i < FramesBetweenSyncs; i++) {
                            input.unPackInt8U();
                            input.unPackRadU();
                            input.unPackRad();
                        }
                        var i = stateIdx;
                        var state = player.stateBuffer[i];
                        player.x = x;
                        player.y = y;
                        player.z = z;
                        player.dx = state.dx;
                        player.dy = state.dy;
                        player.dz = state.dz;
                        player.climbing = state.climbing;
                        player.jumping = state.jumping;
                        var oldKeys = me.controlKeys;
                        for (;i != player.stateIdx; i = Math.mod(i + 1, stateBufferSize)) {
                            state = player.stateBuffer[i];
                            player.controlKeys = state.controlKeys;
                            player.yaw = state.yaw;
                            if (state.jump) player.jump();
                            player.update(state.delta, true);
                            player.stateBuffer[i].x = player.x;
                            player.stateBuffer[i].y = player.y;
                            player.stateBuffer[i].z = player.z;
                            player.stateBuffer[i].dx = player.dx;
                            player.stateBuffer[i].dy = player.dy;
                            player.stateBuffer[i].dz = player.dz;
                            player.stateBuffer[i].jumping = player.jumping;
                        }
                        var dist = Math.length3(player.x - oldx, player.y - oldy, player.z - oldz);
                        if (dist < .2) {
                            if (dist > .02) {
                                player.corrections = FramesBetweenSyncs;
                                player.corrected.dx = player.x - oldx;
                                player.corrected.dy = player.y - oldy;
                                player.corrected.dz = player.z - oldz;
                            }
                            player.x = oldx;
                            player.y = oldy;
                            player.z = oldz;
                            player.dx = olddx;
                            player.dy = olddy;
                            player.dz = olddz;
                        } else {
                            player.corrections = 0;
                        }
                        player.jumping = wasJumping;
                        player.climbing = wasClimbing;
                        if (wasJumping) {
                            player.corrected.dy = 0;
                            player.y = oldy;
                            player.dy = olddy;
                        }
                        player.yaw = oldYaw;
                        player.pitch = oldPitch;
                        player.controlKeys = oldKeys;
                    } else {
                        player.stateIdx = 0;
                        for (var i = 0; i < FramesBetweenSyncs; i++) {
                            player.stateBuffer[i].controlKeys = input.unPackInt8U();
                            player.stateBuffer[i].yaw = input.unPackRadU();
                            player.stateBuffer[i].pitch = input.unPackRad();
                        }
                        player.x = x;
                        if (!player.jumping) player.y = y;
                        player.z = z;
                        player.climbing = climbing;
                    }
                    break;

                  case CommCode.fire:
                    var id = input.unPackInt8U();
                    tv1.x = input.unPackFloat();
                    tv1.y = input.unPackFloat();
                    tv1.z = input.unPackFloat();
                    tv2.x = input.unPackFloat();
                    tv2.y = input.unPackFloat();
                    tv2.z = input.unPackFloat();
                    var seed = input.unPackInt8U();
                    var player = players[id];
                    if (!player) break;
                    if (id != meId) {
                        player.weapon.actor.fire();
                    }
                    mathSeed = seed;
                    player.weapon.fireMunitions(tv1, tv2);
                    break;

                  case CommCode.throwGrenade:
                    var id = input.unPackInt8U();
                    var x = input.unPackFloat();
                    var y = input.unPackFloat();
                    var z = input.unPackFloat();
                    var dx = input.unPackFloat();
                    var dy = input.unPackFloat();
                    var dz = input.unPackFloat();
                    var player = players[id];
                    if (!player) break;
                    player.grenadeCount--;
                    if (id != meId) {
                        player.actor.head.rotation.x = player.pitch;
                        player.actor.mesh.rotation.y = player.yaw;
                    } else {
                        updateAmmoUi();
                    }
                    player.actor.throwGrenade();
                    munitionsManager.throwGrenade(player, {
                        x: x,
                        y: y,
                        z: z
                    }, {
                        x: dx,
                        y: dy,
                        z: dz
                    });
                    break;

                  case CommCode.reload:
                    var id = input.unPackInt8U();
                    if (players[id]) players[id].reload();
                    break;

                  case CommCode.swapWeapon:
                    var id = input.unPackInt8U();
                    var weaponIdx = input.unPackInt8U();
                    if (players[id]) players[id].swapWeapon(weaponIdx);
                    break;

                  case CommCode.hitMe:
                    var hp = input.unPackInt8U();
                    var dx = input.unPackFloat();
                    var dz = input.unPackFloat();
                    me.hp = hp;
                    me.actor.hit();
                    hitIndicator.hit(dx, dz);
                    break;

                  case CommCode.hitThem:
                    var id = input.unPackInt8U();
                    var hp = input.unPackInt8U();
                    var player = players[id];
                    if (!player) break;
                    var numFrags = Math.min(100, player.hp - hp) / 3 + 5;
                    player.hp = hp;
                    player.actor.hit();
                    if (hp > 0) shellFragBurst(player, numFrags, .07, 20);
                    break;

                  case CommCode.respawn:
                    var id = input.unPackInt8U();
                    var x = input.unPackFloat();
                    var y = input.unPackFloat();
                    var z = input.unPackFloat();
                    var player = players[id];
                    if (player) {
                        player.respawn(x, y, z);
                        if (id == meId) {
                            console.log("CommCode.respawn received from server for this player");
                        }
                    }
                    break;

                  case CommCode.changeCharacter:
                    var id = input.unPackInt8U();
                    var classIdx = input.unPackInt8U();
                    var primaryWeaponIdx = input.unPackInt8U();
                    var secondaryWeaponIdx = input.unPackInt8U();
                    var shellColor = input.unPackInt8U();
                    var hatIdx = input.unPackInt8U();
                    var stampIdx = input.unPackInt8U();
                    var primaryWeaponItem = catalog.findItemBy8BitItemId(ItemType.Primary, classIdx, primaryWeaponIdx);
                    var secondaryWeaponItem = catalog.findItemBy8BitItemId(ItemType.Secondary, classIdx, secondaryWeaponIdx);
                    var hatItem = catalog.findItemBy8BitItemId(ItemType.Hat, classIdx, hatIdx);
                    var stampItem = catalog.findItemBy8BitItemId(ItemType.Stamp, classIdx, stampIdx);
                    var player = players[id];
                    if (player) {
                        player.changeCharacter(classIdx, primaryWeaponItem, secondaryWeaponItem, shellColor, hatItem, stampItem);
                    }
                    break;

                  case CommCode.switchTeam:
                    var id = input.unPackInt8U();
                    var toTeam = input.unPackInt8U();
                    var player = players[id];
                    if (player) {
                        player.team = toTeam;
                        player.score = 0;
                        player.kills = 0;
                        player.streak = 0;
                        player.bestGameStreak = 0;
                        if (id == meId) {
                            myTeam = toTeam;
                            setTeamButton();
                        }
                        for (var i = 0; i < playerLimit; i++) {
                            player = players[i];
                            if (player && player.actor) {
                                player.actor.updateTeam();
                            }
                        }
                        rebuildPlayerList();
                    }
                    break;

                  case CommCode.switchTeamFail:
                    openAlertDialog(getLocText("ui_game_fairteams_header"), getLocText("ui_game_fairteams_text"), {
                        label: "OK",
                        width: "8em"
                    });
                    break;

                  case CommCode.ping:
                    ping = Date.now() - pingStartTime;
                    pingTotal += ping;
                    pingSamples++;
                    var el = document.getElementById("ping");
                    if (ping < 100) el.style.color = "#0f0"; else if (ping < 150) el.style.color = "#ff0"; else if (ping < 200) el.style.color = "#f90"; else el.style.color = "#f00";
                    el.innerText = ping + "ms";
                    setTimeout(function() {
                        var output = new Comm.output(1);
                        output.packInt8(CommCode.ping);
                        pingStartTime = Date.now();
                        if (ws) ws.send(output.buffer);
                    }, 1e3);
                    break;

                  case CommCode.notification:
                    notify(input.unPackString(), input.unPackInt8U() * 1e3);
                    break;

                  case CommCode.gameLocked:
                    notify(getLocText("ui_game_locked"), 1e4);
                    break;

                  case CommCode.updateBalance:
                    var newBalance = input.unPackInt32U();
                    console.log("updating balance from server: " + newBalance);
                    playerAccount.currentBalance = newBalance;
                    updateCurrentBalance();
                    break;

                  case CommCode.expireUpgrade:
                    console.log("upgrade has expired");
                    checkUpgrade();
                    break;

                  default:
                    console.log("CommCode error: " + cmd + "/" + String.fromCharCode(cmd) + " - previous cmd: " + JSON.stringify(prevCmd));
                    break;
                }
                prevCmd.push(cmd);
                if (prevCmd.length > 4) prevCmd.shift();
            }
        };
    }
    var SPS;
    var rotInc = Math.PI / 2;
    function iterateXYZ(width, height, depth, options, callback) {
        var opt = options || {};
        opt.step = opt.step || 1;
        opt.x = opt.x || 0;
        opt.y = opt.y || 0;
        opt.z = opt.z || 0;
        for (var x = opt.x; x < width; x += opt.step) {
            for (var y = opt.y; y < height; y += opt.step) {
                for (var z = opt.z; z < depth; z += opt.step) {
                    callback(x, y, z);
                }
            }
        }
    }
    function createMapCells(callback) {
        if (playOffline) {
            minMap = JSON.parse(localStorage.getItem("mapBackup"));
        } else {
            console.log("MAP IDX: " + mapIdx);
            minMap = minMaps[mapIdx];
        }
        if (minMap.sun) {
            gameScene.sunLight.direction = new BABYLON.Vector3(minMap.sun.direction.x, minMap.sun.direction.y, minMap.sun.direction.z);
        } else {
            gameScene.sunLight.direction = new BABYLON.Vector3(.2, 1, .1);
        }
        SPS = new BABYLON.SolidParticleSystem("SPS", gameScene, {
            updatable: true
        });
        SPS.computeParticleColor = false;
        SPS.computeParticleTexture = false;
        SPS.computeParticleRotation = false;
        SPS.recomputeNormals = false;
        var meshIndex = buildMapData(function(str) {
            alert("The following map meshes were not found:\n\n" + str + "\nTry clearing your cache and reload the page!");
        });
        var meshNames = Object.keys(minMap.data);
        function addMeshToMap(keyIdx) {
            if (keyIdx == meshNames.length) {
                callback();
                return;
            }
            var meshName = meshNames[keyIdx];
            var meshData = minMap.data[meshName];
            var meshIdx = meshIndex[meshName];
            var mesh = mapMeshes[meshIdx];
            var pct = Math.floor(keyIdx / meshNames.length * 100);
            var msgs = [ "Laying", "Cracking", "Making omelettes", "Random clucking", "Scratching", "Scrambling", "Roosting", "Beating", "Making bad yolks", "Thinking of egg puns", "Whipping", "Frying", "Poaching", "Doing something REALLY interesting", "Doing your homework, 'cause SOMEONE has to", "What was I doing? Oh, yeah; map!", "Making you wait, just for clucks", "Watching chicken videos" ];
            var msg = msgs[Math.randomInt(0, msgs.length)];
            showSpinner("Building Map", msg + "... " + pct + "%");
            var fields = meshName.split(".");
            mesh.theme = fields[0];
            mesh.colliderType = fields[2];
            mesh.softness = fields[3];
            if (mesh.theme != "SPECIAL") {
                var i = 0;
                var meshArr = Object.values(meshData);
                SPS.addShape(mesh, meshArr.length, {
                    positionFunction: function(particle, idx, shapeIdx) {
                        var rx = meshArr[i].rx || 0;
                        var ry = meshArr[i].ry || 0;
                        var rz = meshArr[i].rz || 0;
                        particle.position.x = meshArr[i].x + .5;
                        particle.position.y = meshArr[i].y + .5;
                        particle.position.z = meshArr[i].z + .5;
                        particle.rotation.x = rx * rotInc;
                        particle.rotation.y = ry * rotInc;
                        particle.rotation.z = rz * rotInc;
                        particle.alive = false;
                        i++;
                    }
                });
            }
            var nextFunction = addMeshToMap.bind(this, keyIdx + 1);
            window.requestAnimationFrame(nextFunction);
        }
        var nextFunction = addMeshToMap.bind(this, 0);
        window.requestAnimationFrame(nextFunction);
    }
    function applyLightMap(onComplete) {
        mapMesh = SPS.buildMesh();
        mapMesh.receiveShadows = true;
        console.log("Casting rays");
        var w = map.width + 1;
        var h = map.height + 1;
        var d = map.depth + 1;
        var lightMap = make3DArray(w, h, d, 1.5);
        var lightDir = gameScene.sunLight.direction.clone();
        lightDir.normalize();
        var lightRay = lightDir.clone();
        lightRay.scaleInPlace(1e3);
        var testStep = lightDir.clone();
        testStep.scaleInPlace(.5);
        iterateXYZ(map.width + 1, map.height + 1, map.depth + 1, null, function(lmx, lmy, lmz) {
            var rays = [];
            var ray = new BABYLON.Ray(new BABYLON.Vector3(lmx, lmy, lmz), lightRay);
            rays.push(ray);
            var testPos = new BABYLON.Vector3(lmx, lmy, lmz);
            testPos.addInPlace(testStep);
            testPos.addInPlace(testStep);
            var cellsChecked = {};
            var hits = 0;
            while (1) {
                if (testPos.x < -1 || testPos.x > map.width || testPos.y < -1 || testPos.y > map.height || testPos.z < -1 || testPos.z > map.depth || hits == rays.length) {
                    break;
                }
                var ox = 0;
                var oy = 0;
                var oz = 0;
                var cx = Math.floor(Math.clamp(testPos.x + ox, 0, map.width - 1));
                var cy = Math.floor(Math.clamp(testPos.y + oy, 0, map.height - 1));
                var cz = Math.floor(Math.clamp(testPos.z + oz, 0, map.depth - 1));
                var checkId = cx + cy * 1e3 + cz * 1e4;
                if (!cellsChecked[checkId]) {
                    cellsChecked[checkId] = true;
                    var cell = map.data[cx][cy][cz];
                    if (cell && cell.idx) {
                        var cellMesh = mapMeshes[cell.idx];
                        if (cellMesh.theme != "SPECIAL") {
                            cellMesh.rotation.x = cell.rx;
                            cellMesh.rotation.y = cell.ry;
                            cellMesh.rotation.z = cell.rz;
                            cellMesh.position.x = cx + .5;
                            cellMesh.position.y = cy + .5;
                            cellMesh.position.z = cz + .5;
                            cellMesh.computeWorldMatrix();
                            for (var ri in rays) {
                                var ray = rays[ri];
                                if (!ray.hit) {
                                    var pickInfo = ray.intersectsMesh(cellMesh, true);
                                    if (pickInfo.hit) {
                                        ray.hit = true;
                                        hits++;
                                    }
                                }
                            }
                            cellMesh.position = BABYLON.Vector3.Zero();
                        }
                    }
                }
                testPos.addInPlace(testStep);
            }
            if (hits > 0) {
                lightMap[lmx][lmy][lmz] = .2;
            }
        });
        console.log("Applying lightmap");
        var colors = mapMesh.getVerticesData(BABYLON.VertexBuffer.ColorKind);
        var positions = mapMesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
        function worker() {
            self.onmessage = function(e) {
                e = e.data;
                var size = .6;
                var samples;
                var sum;
                for (var i = 0; i < e.positions.length / 3; i++) {
                    var ix3 = i * 3;
                    var x = e.positions[ix3];
                    var y = e.positions[ix3 + 1];
                    var z = e.positions[ix3 + 2];
                    samples = 0;
                    sum = 0;
                    iterateXYZ(Math.min(e.w - 1, x + size), Math.min(e.h - 1, y + size), Math.min(e.d - 1, z + size), {
                        x: Math.max(0, x - size),
                        y: Math.max(0, y - size),
                        z: Math.max(0, z - size)
                    }, sumItUp);
                    var l = Math.min(Math.max(sum / samples, .5), 1);
                    e.colors[i * 4] *= l;
                    e.colors[i * 4 + 1] *= l;
                    e.colors[i * 4 + 2] *= l;
                    if (i % 1e3 == 0) {
                        postMessage({
                            progress: Math.floor(i / (e.positions.length / 3) * 100)
                        });
                    }
                }
                function sumItUp(x, y, z) {
                    var cx = Math.round(x);
                    var cy = Math.round(y);
                    var cz = Math.round(z);
                    samples++;
                    sum += e.lightMap[cx][cy][cz];
                }
                function iterateXYZ(width, height, depth, options, callback) {
                    var opt = options || {};
                    opt.step = opt.step || 1;
                    opt.x = opt.x || 0;
                    opt.y = opt.y || 0;
                    opt.z = opt.z || 0;
                    for (var x = opt.x; x < width; x += opt.step) {
                        for (var y = opt.y; y < height; y += opt.step) {
                            for (var z = opt.z; z < depth; z += opt.step) {
                                callback(x, y, z);
                            }
                        }
                    }
                }
                postMessage({
                    colors: e.colors
                });
            };
        }
        var code = worker.toString();
        code = code.substring(code.indexOf("{") + 1, code.lastIndexOf("}"));
        var blob = new Blob([ code ], {
            type: "application/javascript"
        });
        var worker = new Worker(URL.createObjectURL(blob));
        worker.postMessage({
            colors: colors,
            positions: positions,
            lightMap: lightMap,
            w: w,
            h: h,
            d: d
        });
        worker.onmessage = function(m) {
            if (m.data.hasOwnProperty("progress")) {
                showSpinner("Building Map", "Turning on the lights... " + m.data.progress + "%");
            } else {
                mapMesh.updateVerticesData(BABYLON.VertexBuffer.ColorKind, m.data.colors);
                mapMesh.material = gameScene.getMaterialByName("map");
                mapMesh.freezeWorldMatrix();
                if (!noSkybox) {
                    var skyboxName = minMap.skybox || "default";
                    var skybox = BABYLON.MeshBuilder.CreateBox("skyBox", {
                        size: 100
                    }, gameScene);
                    skybox.infiniteDistance = true;
                    var skyboxMaterial = new BABYLON.StandardMaterial("skyBox", gameScene);
                    skyboxMaterial.backFaceCulling = false;
                    skyboxMaterial.fogEnabled = false;
                    skyboxMaterial.reflectionTexture = new BABYLON.CubeTexture("img/skyboxes/" + skyboxName + "/skybox", gameScene);
                    skyboxMaterial.reflectionTexture.coordinatesMode = BABYLON.Texture.SKYBOX_MODE;
                    skyboxMaterial.diffuseColor = new BABYLON.Color3(0, 0, 0);
                    skyboxMaterial.specularColor = new BABYLON.Color3(0, 0, 0);
                    skybox.material = skyboxMaterial;
                }
                onComplete();
            }
        };
    }
    function buildMap(onComplete) {
        showSpinner("Building Map", "Hold on!");
        createMapCells(function() {
            showSpinner("Building Map", "Turning on the lights...");
            requestAnimationFrame(applyLightMap.bind(this, complete));
        });
        function complete() {
            hideSpinner();
            onComplete();
        }
    }
    function update() {
        var fps = engine.getFps();
        fpsTotal += fps;
        fpsSamples++;
        if (fpsSamples % 10 == 0) {
            fpsAverage = fpsTotal / fpsSamples;
            var fpsEl = document.getElementById("FPS");
            fpsEl.innerText = Math.floor(fps + .5);
            var barEl = document.getElementById("healthBar");
            var hpEl = document.getElementById("healthHp");
            var r = 2.3 - viewingPlayer.hp / 43.478;
            barEl.setAttribute("stroke-dashoffset", r * 6.2832 + "em");
            hpEl.innerText = Math.floor(viewingPlayer.hp);
        }
        var currentTimeStamp = performance.now();
        if (pingSamples > 10) {
            highestPing = Math.max(highestPing, ping);
        }
        var step = 1e3 / 60;
        var delta = 1;
        while (lastTimeStamp < currentTimeStamp) {
            lastTimeStamp += step;
            if (!freezeFrame) {
                for (var i = 0; i < players.length; i++) {
                    var player = players[i];
                    if (player) {
                        player.chatLineCap = Math.min(player.chatLineCap + delta / 120, 3);
                        if (player.playing) {
                            player.update(delta);
                            player.actor.handsToWeaponSkeleton();
                            if (player.actor) {
                                player.actor.update(delta);
                            }
                        }
                    }
                }
                if (spatula) {
                    spatula.update(delta);
                }
            } else {
                me.update(delta);
                me.actor.update(delta);
            }
            if (me) {
                me.stateBuffer[me.stateIdx] = {
                    delta: delta,
                    yaw: me.yaw,
                    fire: false,
                    jumping: me.jumping,
                    climbing: me.climbing,
                    x: me.x,
                    y: me.y,
                    z: me.z,
                    dx: me.dx,
                    dy: me.dy,
                    dz: me.dz,
                    controlKeys: me.controlKeys
                };
                if (me.stateIdx % FramesBetweenSyncs == 0 && ws.readyState == ws.OPEN && me.hp > 0 && !freezeFrame) {
                    serverSync();
                }
                hitIndicator.update(delta);
                reticle.update(delta);
                if (me.weapon && me.weapon.ammo.rounds == 0) {
                    if (me.stateIdx % 20 == 0) {
                        document.getElementById("ammo").style.color = "#f00";
                    } else if (me.stateIdx % 20 == 10) {
                        document.getElementById("ammo").style.color = "#fff";
                    }
                }
                if (grenadePowerUp == true) {
                    grenadeThrowPower = Math.min(grenadeThrowPower + .015, 1);
                    if (grenadeThrowPower > 0) {
                        document.getElementById("grenadeThrowContainer").style.visibility = "visible";
                        document.getElementById("grenadeThrow").style.height = grenadeThrowPower * 100 + "%";
                    }
                }
            }
            if (!freezeFrame) {
                munitionsManager.update(delta);
                itemManager.update(delta);
                updateParticles(explosionSmokeManager, delta);
                updateParticles(explosionFireManager, delta);
                updateParticles(shellFragManager, delta);
                updateParticles(yolkManager, delta);
            }
            if (mapOverview) {
                mapOverviewAxis += .002 * delta;
                camera.position.x = Math.sin(mapOverviewAxis) * map.height + map.width / 2;
                camera.position.z = Math.cos(mapOverviewAxis) * map.height + map.depth / 2;
                camera.setTarget(new BABYLON.Vector3(map.width / 2, map.height / 4, map.depth / 2));
            }
        }
    }
    function hitPlayer() {}
    var pingStartTime;
    function serverSync() {
        if (me) {
            var output = new Comm.output(3 + FramesBetweenSyncs * 5);
            output.packInt8(CommCode.sync);
            output.packInt8(me.stateIdx);
            output.packInt8(me.shotsQueued);
            var startIdx = Math.mod(me.stateIdx - FramesBetweenSyncs, stateBufferSize);
            for (var i = 0; i < FramesBetweenSyncs; i++) {
                var idx = Math.mod(startIdx + i, stateBufferSize);
                output.packInt8(me.stateBuffer[idx].controlKeys);
                output.packRadU(me.stateBuffer[idx].yaw);
                output.packRad(me.stateBuffer[idx].pitch);
            }
            ws.send(output.buffer);
            me.shotsQueued = 0;
        }
    }
    function switchTeamDialog() {
        var str;
        if (me.team == 1) {
            str = 'Switch to team<h1 class="redTeam">RED?</h1>Your score will be reset!';
        } else {
            str = 'Switch to team<h1 class="blueTeam">BLUE?</h1>Your score will be reset!';
        }
        openAlertDialog("", str, {
            label: "Yes",
            width: "5em",
            onclick: switchTeam
        }, {
            label: "No",
            width: "5em",
            onclick: closeAlertDialog
        });
    }
    function switchTeam() {
        closeAlertDialog();
        var output = new Comm.output(1);
        output.packInt8(CommCode.switchTeam);
        ws.send(output.buffer);
    }
    function setTeamButton() {
        var teamButton = document.getElementById("teamButton");
        if (myTeam == 1) {
            teamButton.innerText = "Join RED Team";
            teamButton.className = "ssbutton red";
        } else {
            teamButton.innerText = "Join BLUE Team";
            teamButton.className = "ssbutton blue";
        }
    }
    function refreshGameState() {
        for (var i = 0; i < playerLimit; i++) {
            var player = players[i];
            if (player) {
                player.actor.remove();
                delete players[player.id];
            }
        }
        itemManager.recycleAllItems();
        var output = new Comm.output(1);
        output.packInt8(CommCode.refreshGameState);
        ws.send(output.buffer);
    }
    function addPlayer(playerData) {
        if (playerData.id == meId) viewingPlayerId = playerData.id;
        var player = new Player(playerData, gameScene);
        if (player.id == meId) {
            me = player;
            viewingPlayer = player;
            me.ws = ws;
            updateAmmoUi();
        }
        if (!player.playing) player.actor.removeFromPlay();
        players[playerData.id] = player;
        rebuildPlayerList();
    }
    function removePlayer(playerId) {
        var player = players[playerId];
        if (playerId == meId) {
            console.log("Tried to remove ME");
            return;
        }
        if (player) {
            player.actor.remove();
            delete players[playerId];
            rebuildPlayerList();
        }
    }
    function getTeamKills() {
        var teamKills = [ 0, 0, 0 ];
        for (var i = 0; i < playerLimit; i++) {
            var player = players[i];
            if (player) {
                teamKills[player.team] += player.score;
            }
        }
        var leadingTeam = 0;
        if (teamKills[1] > teamKills[2]) {
            leadingTeam = 1;
        } else if (teamKills[2] > teamKills[1]) {
            leadingTeam = 2;
        }
        return {
            score: teamKills,
            leader: leadingTeam
        };
    }
    var lastLeadingTeam = 1;
    function rebuildPlayerList() {
        var playerIdxs = [];
        for (var i = 0; i < players.length; i++) {
            if (players[i]) {
                playerIdxs.push(i);
            }
        }
        if (isTeamGame) {
            var teams = getTeamKills();
            if (teams.leader > 0) lastLeadingTeam = teams.leader;
            teams.score[lastLeadingTeam] += 1e5;
            playerIdxs.sort(function(a, b) {
                return players[b].score + teams.score[players[b].team] - (players[a].score + teams.score[players[a].team]);
            });
        } else {
            playerIdxs.sort(function(a, b) {
                return players[b].score - players[a].score;
            });
        }
        var list = document.getElementById("playerList").children;
        var i;
        for (i = 0; i < playerIdxs.length; i++) {
            var player = players[playerIdxs[i]];
            var slot = list[i];
            var nameAndScore = slot.children[0];
            var name = nameAndScore.children[0];
            var score = nameAndScore.children[1];
            var icons = slot.children[1];
            slot.style.display = "table-row";
            name.innerText = player.name;
            if (player.id != meId) {
                var askClosure = function(playerId, uniqueId) {
                    var bootPlayerClosure = function(playerId, uniqueId) {
                        return function() {
                            bootPlayer(playerId, uniqueId);
                        };
                    };
                    var mutePlayerClosure = function(playerId, uniqueId) {
                        return function() {
                            mutePlayer(playerId, uniqueId);
                        };
                    };
                    return function() {
                        openAlertDialog(players[playerId].name, "", {
                            label: "Close",
                            onclick: closeAlertDialog
                        });
                        var container = document.createElement("div");
                        container.style.textAlign = "center";
                        container.innerHTML = getLocText("ui_game_playeractions_header") + "<br><br>";
                        document.getElementById("alertMessage").appendChild(container);
                        var b = document.createElement("button");
                        b.style.display = "inline-block";
                        if (players[playerId].muted) {
                            b.className = "ssbutton blue";
                            b.innerHTML = getLocText("ui_game_playeractions_unmute");
                        } else {
                            b.className = "ssbutton orange";
                            b.innerHTML = getLocText("ui_game_playeractions_mute");
                        }
                        b.style.width = "10em";
                        b.style.height = "2.5em";
                        b.style.margin = "0.5em";
                        b.onclick = mutePlayerClosure(playerId, uniqueId);
                        container.appendChild(b);
                        if (isGameOwner) {
                            var b = document.createElement("button");
                            b.className = "ssbutton red";
                            b.style.display = "inline-block";
                            b.innerHTML = getLocText("ui_game_playeractions_boot");
                            b.style.width = "10em";
                            b.style.height = "2.5em";
                            b.style.margin = "0.5em";
                            b.onclick = bootPlayerClosure(playerId, uniqueId);
                            container.appendChild(b);
                        }
                    };
                };
                slot.addEventListener("click", askClosure(player.id, player.uniqueId), false);
                slot.style.pointerEvents = "all";
                slot.style.cursor = "pointer";
            }
            score.innerText = player.score;
            if (player.id == meId) {
                nameAndScore.className = "thisPlayer";
                nameAndScore.style.background = teamColors.meBackground[player.team];
            } else {
                nameAndScore.className = "otherPlayer";
                nameAndScore.style.background = teamColors.themBackground[player.team];
                nameAndScore.style.color = teamColors.text[player.team];
            }
            icons.innerText = "";
            if (player.upgradeProductId && player.upgradeProductId > 0) icons.innerText += "🥚";
            if (player.muted) icons.innerText += "🚫";
        }
        while (i < playerLimit) {
            list[i].style.display = "none";
            i++;
        }
    }
    function bootPlayer(playerId, uniqueId) {
        if (isGameOwner && players[playerId] && players[playerId].uniqueId == uniqueId) {
            var output = new Comm.output(4);
            output.packInt8(CommCode.bootPlayer);
            output.packInt8(playerId);
            output.packInt16(players[playerId].uniqueId);
            ws.send(output.buffer);
        }
        closeAlertDialog();
    }
    function mutePlayer(playerId, uniqueId) {
        var player = players[playerId];
        if (player && player.uniqueId == uniqueId) {
            if (player.muted) {
                player.muted = false;
                player.name = player.oldName;
            } else {
                player.muted = true;
                player.oldName = player.name;
                player.name = randomName();
            }
            player.actor.setupNameSprite();
            rebuildPlayerList();
        }
        closeAlertDialog();
    }
