    var lastKey = null;
    function captureKeys() {
        lastKey = null;
        document.onkeydown = onKeyDown;
        document.onkeyup = onKeyUp;
    }
    function releaseKeys() {
        document.onkeydown = null;
        document.onkeyup = null;
    }
    function inputDown(code) {
        if (!me.playing || !document.pointerLockElement) return;
        var control = inputToControlMap[code];
        handleInputDown(control);
    }
    function handleInputDown(control) {
        switch (control) {
          case "up":
          case "down":
          case "left":
          case "right":
            var bit = CONTROL[control];
            me.controlKeys |= bit;
            me.stateBuffer[me.stateIdx].controlKeys = me.controlKeys;
            break;

          case "jump":
            if (me.lastTouchedGround > 0 && Date.now() > me.lastTouchedGround + 100) {
                if (me.jump()) {
                    var output = new Comm.output(1);
                    output.packInt8(CommCode.jump);
                    ws.send(output.buffer);
                }
            }
            break;

          case "fire":
            if (document.pointerLockElement && me) {
                me.pullTrigger();
            }
            break;

          case "grenade":
            if (document.pointerLockElement && me && !grenadePowerUp && me.canSwapOrReload() && me.grenadeCount > 0) {
                grenadePowerUp = true;
                grenadeThrowPower = -.15;
            }
            break;

          case "scope":
            if (settings.holdToAim) {
                me.actor.scopeIn();
            } else {
                if (me.actor.scope) {
                    me.actor.scopeOut();
                } else {
                    me.actor.scopeIn();
                }
            }
            break;

          case "reload":
            me.reload();
            break;

          case "weapon":
            me.swapWeapon(me.weaponIdx == 0 ? 1 : 0);
            break;
        }
    }
    function inputUp(code) {
        if (!me.playing || !document.pointerLockElement) return;
        var control = inputToControlMap[code];
        handleInputUp(control);
    }
    function handleInputUp(control) {
        switch (control) {
          case "fire":
            if (me.weapon) {
                me.releaseTrigger();
            }
            break;

          case "scope":
            if (settings.holdToAim) me.actor.scopeOut();
            break;

          case "grenade":
            if (document.pointerLockElement && me && grenadePowerUp) {
                document.getElementById("grenadeThrowContainer").style.visibility = "hidden";
                grenadePowerUp = false;
                me.throwGrenade(grenadeThrowPower);
            }
            break;

          case "up":
          case "down":
          case "left":
          case "right":
          case "jump":
            var bit = CONTROL[control];
            me.controlKeys ^= me.controlKeys & bit;
            break;
        }
    }
