    function onChatKeyDown(e) {
        e = e || window.event;
        var key = e.key;
        chatInEl.value = fixStringWidth(chatInEl.value, 280);
        switch (key) {
          case "Enter":
            var text = chatInEl.value.trim();
            if (text != "" && text.indexOf("<") < 0) {
                var output = new Comm.output(2 + text.length * 2);
                output.packInt8(CommCode.chat);
                output.packString(text);
                ws.send(output.buffer);
                addChat(text, me);
                me.chatLineCap--;
            }

          case "Tab":
            initChatIn();
            e.preventDefault();
            e.stopPropagation();
            captureKeys();
            break;
        }
    }
    function onKeyDown(e) {
        e = e || window.event;
        var key = e.key;
        if (key == lastKey) return;
        lastKey = key;
        if (!grenadePowerUp && me.controlKeys == 0 && key == "Enter" && settings.enableChat) {
            if (me.chatLineCap > 0) {
                releaseKeys();
                chatInEl.style.background = "rgba(0, 0, 0, 0.5)";
                chatInEl.value = "";
                chatInEl.focus();
                lastKey = null;
                chatting = true;
            }
            return;
        }
        var k = ("" + key).toLocaleUpperCase();
        if (k == " ") {
            k = "SPACE";
            e.preventDefault();
        }
        if (debug) {
            if (k == "`") {
                debugDump();
                return;
            }
            if (k == "\\") {
                freezeFrame = true;
                for (var i = 0; i < gameScene.particleSystems.length; i++) {
                    gameScene.particlesPaused = true;
                }
                for (var i = 0; i < playerLimit; i++) {
                    if (players[i] && players[i].actor) {
                        players[i].actor.mesh.setVisible(true);
                        players[i].actor.showNameSprite();
                        players[i].actor.positionNameSprite();
                    }
                }
                ws.close();
            }
        }
        inputDown(k);
    }
    function onKeyUp(e) {
        e = e || window.event;
        var key = e.key;
        if (key == lastKey) lastKey = null;
        var k = ("" + key).toLocaleUpperCase();
        if (k == " ") {
            k = "SPACE";
            e.preventDefault();
        }
        inputUp(k);
    }
