    Reticle.prototype.fireDenied = function() {
        this.readyBrackets.className = "";
        var that = this;
        setTimeout(function() {
            that.readyBrackets.className = "notReady";
        }, 10);
    };
    Reticle.prototype.update = function(delta) {
        if (me.weapon) {
            for (var i = 0; i < 4; i++) {
                var spread = me.shotSpread + me.weapon.subClass.accuracy;
                var ch = this.crosshairs[i];
                ch.style.transform = "rotate(" + i * 90 + "deg) translateY(" + (spread * .069 + .12) + "em)";
            }
            if (me.weapon.subClass.minRange) {
                var ray = camera.getForwardRay();
                ray.direction.scaleInPlace(1e3);
                ray.origin = me.actor.eye.getAbsolutePosition();
                var res = Collider.rayCollidesWithMap(ray.origin, ray.direction, Collider.projectileCollidesWithCell);
                if (res) {
                    var range = BABYLON.Vector3.Distance(ray.origin, res.pick.pickedPoint);
                    if (range - .01 >= me.weapon.subClass.minRange) {
                        this.readyBrackets.className = "ready";
                    } else {
                        this.readyBrackets.className = "notReady";
                    }
                } else {
                    this.readyBrackets.className = "ready";
                }
            }
        }
    };
    Reticle.prototype.resize = function() {};
