    Customizer.prototype.setupWeaponStats = function() {
        var setupWeaponStatsInList = function(weaponList) {
            for (var i = 0; i < weaponList.length; i++) {
                var weapon = weaponList[i].item_data.class;
                for (var key in weaponStats) {
                    if (weaponStats[key].flip) {
                        weaponStats[key].max = Math.max(weaponStats[key].max, -weapon[key]);
                        weaponStats[key].min = Math.min(weaponStats[key].min, -weapon[key]);
                    } else {
                        weaponStats[key].max = Math.max(weaponStats[key].max, weapon[key]);
                        weaponStats[key].min = 0;
                    }
                }
            }
        };
        setupWeaponStatsInList(catalog.primaryWeapons);
        setupWeaponStatsInList(catalog.secondaryWeapons);
    };
