    var flashColors = [ new BABYLON.Color3(1, 1, 0), new BABYLON.Color3(0, .5, 1), new BABYLON.Color3(1, 0, 0) ];
    function GrenadeActor(grenade, scene) {
        this.grenade = grenade;
        this.scene = grenade.scene;
        this.mesh = this.scene.cloneMesh("grenade");
        this.mesh.setEnabled(false);
        this.beep = false;
        this.flashColor = null;
    }
    GrenadeActor.prototype.throw = function() {
        this.mesh.setEnabled(true);
        this.mesh.position.x = this.grenade.x;
        this.mesh.position.y = this.grenade.y;
        this.mesh.position.z = this.grenade.z;
        if (this.grenade.player.id == meId) {
            this.flashColor = flashColors[0];
        } else {
            this.flashColor = flashColors[this.grenade.player.team];
        }
        Sounds.grenade.pin.play(this.mesh.position);
        this.bounce();
    };
    GrenadeActor.prototype.update = function() {
        this.mesh.position.x = this.grenade.x;
        this.mesh.position.y = this.grenade.y;
        this.mesh.position.z = this.grenade.z;
        this.mesh.rotation.x += this.rx;
        this.mesh.rotation.y += this.ry;
        this.mesh.rotation.z += this.rz;
        if (Math.sqrt(this.grenade.ttl) % 2 > 1) {
            if (this.beep == false) {
                Sounds.grenade.beep.play(this.mesh.position);
                this.beep = true;
            }
            this.mesh.emissiveColor = this.flashColor;
        } else {
            this.mesh.emissiveColor = BABYLON.Color3.Black();
            this.beep = false;
        }
    };
    GrenadeActor.prototype.remove = function() {
        this.mesh.setEnabled(false);
    };
    GrenadeActor.prototype.bounce = function() {
        var s = Math.length3(this.grenade.dx, this.grenade.dy, this.grenade.dz);
        this.rx = (Math.random() * 2 - 1) * s;
        this.ry = (Math.random() * 2 - 1) * s;
        this.rz = (Math.random() * 2 - 1) * s;
    };
    GrenadeActor.prototype.stop = function() {
        this.rx = 0;
        this.ry = 0;
        this.rz = 0;
    };
