    function openServerList() {
        openAlertDialog("Servers", "", {
            label: "Close",
            width: "6em",
            onclick: closeServerList
        });
        var serverItem = document.getElementById("serverItem");
        var list = document.createElement("form");
        var barColors = [ "lime", "yellow", "orange", "red" ];
        for (var i = 0; i < servers.length; i++) {
            var server = serverItem.cloneNode(true);
            server.style.display = "block";
            var checkEl = server.children[0].children[0];
            var nameEl = server.children[0].children[1];
            var playersEl = server.children[0].children[2];
            var barEl = server.children[0].children[3];
            var offlineEl = server.children[0].children[4];
            var msEl = server.children[0].children[5];
            nameEl.innerText = servers[i].name;
            checkEl.value = i;
            var border;
            var pingColor;
            if (servers[i].ping) {
                border = Math.min(5.4, Math.max(0, (servers[i].ping - 50) / 65)) + .1;
                pingColor = Math.min(3, Math.floor(servers[i].ping / 100));
                barEl.style.display = "block";
                offlineEl.style.display = "none";
                barEl.style.backgroundColor = barColors[pingColor];
                barEl.style.borderRight = border + "em solid var(--egg-brown)";
                msEl.innerText = servers[i].ping + "ms";
            } else {
                barEl.style.display = "none";
                offlineEl.style.display = "block";
            }
            list.appendChild(server);
        }
        document.getElementById("alertMessage").appendChild(list);
        list.children[selectedServer].children[0].children[0].checked = true;
        list.addEventListener("change", function(e) {
            selectServer(e.target.value);
        });
    }
    function closeServerList() {
        closeAlertDialog();
    }
    function pingServers(autoSelect, callback) {
        var serverSelected = false;
        var serversPinged = 0;
        console.log("Pinging servers");
        for (var i = 0; i < servers.length; i++) {
            servers[i].ping = 0;
            (function(serverIdx) {
                var server = servers[serverIdx];
                var pinger = new WebSocket(getGameServerUrl(server));
                console.log("Connecting to " + server.name);
                pinger.binaryType = "arraybuffer";
                var startTime;
                var timeout = setTimeout(function() {
                    console.log(server.name + " timed out");
                    server.ping = 1e3;
                    pinged();
                    pinger.close();
                }, 1e3);
                pinger.onopen = function(e) {
                    console.log("Pinging " + server.name);
                    var output = new Comm.output(1);
                    output.packInt8(CommCode.ping);
                    pinger.send(output.buffer);
                    startTime = Date.now();
                };
                pinger.onmessage = function(e) {
                    clearTimeout(timeout);
                    var pingTime = Date.now() - startTime;
                    server.ping = pingTime;
                    pinger.close();
                    if (autoSelect && !serverSelected) {
                        serverSelected = true;
                        selectServer(serverIdx);
                    }
                    pinged();
                    console.log(server.name + ": " + pingTime);
                };
                pinger.onerror = function(e) {
                    clearTimeout(timeout);
                    server.ping = 1e3;
                    pinged();
                };
            })(i);
        }
        function pinged() {
            if (++serversPinged == servers.length && callback) {
                callback();
            }
        }
    }
