    function fetchTwitchStreams() {
        var streamsEl = document.getElementById("twitchStreams");
        streamsEl.innerHTML = "";
        console.log(url);
        var url = parsedUrl.root;
        getRequest(url + "twitchStreams.json?" + Date.now(), function(err, res) {
            if (!err) {
                var twitchStreams = JSON.parse(res);
                var keys = Object.keys(twitchStreams);
                keys.sort(function(a, b) {
                    return twitchStreams[b].viewers - twitchStreams[a].viewers;
                });
                keys.forEach(function(k) {
                    var stream = twitchStreams[k];
                    var container = document.createElement("div");
                    container.className = "twitchRow clickable";
                    container.onclick = function(name) {
                        return function() {
                            window.open("https://twitch.tv/" + name, "_blank");
                        };
                    }(stream.name);
                    var avatar = document.createElement("img");
                    avatar.className = "twitchAvatar";
                    avatar.src = "img/twitchAvatars/" + stream.avatar;
                    var name = document.createElement("div");
                    name.className = "twitchName";
                    name.innerText = stream.name;
                    var viewers = document.createElement("div");
                    viewers.className = "twitchViewers";
                    viewers.innerText = stream.viewers + " viewer";
                    if (stream.viewers > 1) viewers.innerText += "s";
                    container.appendChild(avatar);
                    container.appendChild(name);
                    container.appendChild(viewers);
                    streamsEl.appendChild(container);
                });
            }
        }, function(err) {
            var container = document.createElement("div");
            container.className = "twitchRow";
            var text = document.createElement("div");
            text.className = "twitchViewers";
            text.innerText = "No streams currently available";
            container.appendChild(text);
            streamsEl.appendChild(container);
        });
    }
    function clearSettings() {
        localStorage.removeItem("volume");
        localStorage.removeItem("mouseSensitivity");
        localStorage.removeItem("mouseInvert");
        localStorage.removeItem("holdToAim");
        localStorage.removeItem("enableChat");
        localStorage.removeItem("autoDetail");
        localStorage.removeItem("shadowsEnabled");
        localStorage.removeItem("highRes");
        localStorage.removeItem("controlConfig");
        loadSettings();
    }
    function loadSettings() {
        settings.volume = getStoredNumber("volume", 1);
        settings.mouseSensitivity = Math.max(Math.min(11, getStoredNumber("mouseSensitivity", 5)), 0);
        settings.mouseInvert = getStoredNumber("mouseInvert", 1);
        settings.holdToAim = getStoredBool("holdToAim", true);
        settings.enableChat = getStoredBool("enableChat", false);
        settings.autoDetail = getStoredBool("autoDetail", true);
        settings.shadowsEnabled = getStoredBool("shadowsEnabled", true);
        settings.highRes = getStoredBool("highRes", true);
        inputToControlMap = {
            W: "up",
            S: "down",
            A: "left",
            D: "right",
            SPACE: "jump",
            "MOUSE 0": "fire",
            SHIFT: "scope",
            R: "reload",
            E: "weapon",
            Q: "grenade"
        };
        var storedControlMap = JSON.parse(localStorage.getItem("controlConfig"));
        for (var sk in storedControlMap) {
            Object.keys(inputToControlMap).forEach(function(ik) {
                if (inputToControlMap[ik] == storedControlMap[sk]) {
                    delete inputToControlMap[ik];
                }
            });
            inputToControlMap[sk] = storedControlMap[sk];
        }
        for (var p in inputToControlMap) {
            var ps = "" + p;
            if (inputToControlMap.hasOwnProperty(ps) && ps != ps.toLocaleUpperCase()) {
                delete inputToControlMap[ps];
                inputToControlMap[ps.toLocaleUpperCase()] = inputToControlMap[p];
            }
        }
        configureSettingsMenu();
    }
    var settingsKeyNames = [ "up", "down", "left", "right", "jump", "fire", "scope", "reload", "weapon", "grenade" ];
    var settingsKeyCells = {};
    function initSettingsMenu() {
        var container = document.getElementById("bindingsContainer");
        for (var k in settingsKeyNames) {
            var row = document.createElement("div");
            var keyCell = document.createElement("span");
            keyCell.className = "box defined";
            keyCell.innerText = getLocText("ui_settings_undefined");
            keyCell.tabIndex = 1;
            keyCell.id = settingsKeyNames[k];
            keyCell.onmousedown = configKey;
            keyCell.onwheel = configKey;
            settingsKeyCells[settingsKeyNames[k]] = keyCell;
            row.appendChild(keyCell);
            var nameCell = document.createElement("span");
            nameCell.className = "label";
            nameCell.innerText = getLocText("ui_settings_bind_" + settingsKeyNames[k]);
            row.appendChild(nameCell);
            container.appendChild(row);
        }
    }
    function configureSettingsMenu() {
        for (var k in inputToControlMap) {
            var el = settingsKeyCells[inputToControlMap[k]];
            if (el) {
                el.innerText = ("" + k).toLocaleUpperCase();
            }
        }
        document.getElementById("volume").value = settings.volume;
        document.getElementById("mouseSensitivity").value = settings.mouseSensitivity;
        document.getElementById("mouseInvert").checked = settings.mouseInvert == -1;
        document.getElementById("holdToAim").checked = settings.holdToAim;
        document.getElementById("enableChat").checked = settings.enableChat;
        document.getElementById("autoDetail").checked = settings.autoDetail;
        document.getElementById("shadowsEnabled").checked = settings.shadowsEnabled;
        document.getElementById("highRes").checked = settings.highRes;
        setDetailSettingsVisibility(settings.autoDetail);
    }
    var controlEl;
    function refactorConfigKeys(el) {
        var els = document.getElementsByClassName("box defined");
        var elList = Array.prototype.slice.call(els);
        elList.forEach(function(otherEl) {
            if (otherEl != el && otherEl.innerText == el.innerText) {
                delete inputToControlMap[otherEl.innerText];
                otherEl.className = "box undefined";
                otherEl.innerText = getLocText("ui_settings_undefined");
            }
        });
    }
    function setControl(el) {
        refactorConfigKeys(el);
        delete inputToControlMap[el.oldText];
        inputToControlMap[el.innerText] = el.id;
        controlEl = null;
        window.onkeydown = null;
        window.onkeyup = null;
        localStorage.setItem("controlConfig", JSON.stringify(inputToControlMap));
    }
    function configKey(e) {
        var el = e.target;
        e = e || window.event;
        if (el == controlEl) {
            if (e.button == 1) window.event.preventDefault();
            el.className = "box defined";
            if (e.wheelDelta != undefined) {
                if (e.wheelDeltaY > 0) {
                    el.innerText = "WHEEL UP";
                } else if (e.wheelDeltaY < 0) {
                    el.innerText = "WHEEL DOWN";
                }
            } else {
                el.innerText = "MOUSE " + e.button;
            }
            setControl(el);
        } else {
            if (controlEl) {
                controlEl.className = "box defined";
                controlEl.innerText = controlEl.oldText;
            }
            el.oldText = el.innerText;
            el.className = "box active";
            el.innerText = getLocText("ui_settings_bindinput");
            controlEl = el;
            el.focus();
            window.onkeydown = function(e) {
                e = e || window.event;
                var key = e.key;
                if (key == "Escape" || key == "Tab" || key == "Enter") {
                    el.className = "box defined";
                    el.innerText = el.oldText;
                    controlEl = null;
                } else {
                    if (key == " ") {
                        key = "space";
                        e.preventDefault();
                    }
                    el.className = "box defined";
                    el.innerText = key.toLocaleUpperCase();
                    setControl(el);
                    e.stopPropagation();
                    return false;
                }
            };
            window.onkeyup = function(e) {
                e.stopPropagation();
                return false;
            };
        }
    }
    function missingImportantBrowserFeatures() {
        document.exitPointerLock = document.exitPointerLock || document.mozExitPointerLock || document.webkitExitPointerLock;
        var str = "";
        var missingFeatures = 0;
        if (!BABYLON.Engine.isSupported()) {
            str += '<li>WebGL (<a href="https://shellshock.io/faq.html#webgl" target="_window">More info</a>)';
            missingFeatures++;
        }
        if (!document.exitPointerLock || navigator.userAgent.indexOf("10.1.2 Safari") >= 0) {
            str += '<li>Pointer Lock (<a href="https://shellshock.io/faq.html#pointerlock" target="_window">More info</a>)';
            missingFeatures++;
        }
        if (!localStorage) {
            str += "<li>LocalStorage";
            missingFeatures++;
        }
        var e = new KeyboardEvent("");
        if (e.key === undefined) {
            str += "<li>KeyboardEvent.key";
            missingFeatures++;
        }
        if (missingFeatures > 0) {
            if (missingFeatures == 1) {
                str = "Your browser is missing a feature that Shell Shockers requires:<br><ul>" + str + "</ul>";
            } else {
                str = "Your browser is missing features that Shell Shockers requires:<br><ul>" + str + "</ul>";
            }
            str += "Downloading the latest version of your browser of choice will usually correct this. Internet Explorer is not supported.";
            openAlertDialog("Oh, no!", '<div style="text-align: left">' + str + "</div>");
            return true;
        }
        return false;
    }
