    function openLoginDialog() {
        openAlertDialog("", '<div id="firebaseui-auth-container"></div>', {
            label: "Close",
            width: "8em",
            onclick: closeAlertDialog
        });
        if (!firebaseUi) {
            firebaseUi = new firebaseui.auth.AuthUI(firebase.auth());
        }
        var uiConfig = {
            callbacks: {
                signInSuccessWithAuthResult: function(authResult, redirectUrl) {
                    var user = authResult.user;
                    var emailVerified = user.emailVerified;
                    var credential = authResult.credential;
                    var isNewUser = authResult.additionalUserInfo.isNewUser;
                    var providerId = authResult.additionalUserInfo.providerId;
                    var operationType = authResult.operationType;
                    closeAlertDialog();
                    if (!emailVerified && providerId == "password") {
                        if (isNewUser) {
                            user.sendEmailVerification();
                            openAlertDialog("Check Your Email", "An email has been sent to:<br><h2>" + user.email + "</h2>Click on the enclosed link to complete your registration.", {
                                label: "OK",
                                width: "6em",
                                onclick: closeAlertDialog
                            });
                        } else {
                            openAlertDialog("Check Your Email", "An email was sent to:<br><h2>" + user.email + '</h2>Click on the enclosed link to complete your registration,<br>or click "Resend" to send a new email.', {
                                label: "OK",
                                width: "6em",
                                onclick: closeAlertDialog
                            }, {
                                label: "Resend",
                                width: "6em",
                                onclick: function() {
                                    user.sendEmailVerification();
                                    closeAlertDialog();
                                }
                            });
                        }
                    } else {
                        console.log("calling loggedIn from signInSuccessWithAuthResult callback");
                        loggedIn(user);
                    }
                    return false;
                },
                uiShown: function(e) {}
            },
            credentialHelper: firebaseui.auth.CredentialHelper.NONE,
            signInFlow: "popup",
            signInOptions: [ {
                provider: firebase.auth.EmailAuthProvider.PROVIDER_ID,
                requireDisplayName: false
            }, firebase.auth.FacebookAuthProvider.PROVIDER_ID, firebase.auth.GoogleAuthProvider.PROVIDER_ID ],
            tosUrl: "http://www.bluewizard.com/terms"
        };
        firebaseUi.start("#firebaseui-auth-container", uiConfig);
    }
