    function onResourcesLoaded() {
        document.getElementById("mainMenu").style.display = "block";
        document.getElementById("username").disabled = false;
        showCornerButtons();
        resize();
        hideSpinner();
        customizer.startRendering();
        consent = localStorage.getItem("consent");
        if (consent) consent = JSON.parse(consent);
        if (isFromEU && !consent) openConsentNotification();
        aiptag.consented = consent && consent.ofAge && consent.targetedAds || !isFromEU;
        console.log("AIP consent: " + aiptag.consented);
    }
    function swiftShaderCheck() {
        if (engine.getGlInfo()["renderer"] == "Google SwiftShader" && !localStorage.getItem("swiftShaderNotice")) {
            var str = 'It looks like your graphics card is on Chrome\'s blacklist for some reason. The game will still run, but very slowly. To change this, enter "chrome://flags" in your address bar, search for "Override software rendering list", and enable it.<br><br>CAUTION: The blacklist exists for a reason. This may make your system unstable. Make sure you save anything you\'re working on before trying it!';
            openAlertDialog("SwiftShader? GROSS!", '<div style="text-align: left">' + str + "</div>", "OK");
            localStorage.setItem("swiftShaderNotice", true);
            return true;
        }
        return false;
    }
    function getRequest(url, callback) {
        var req = new XMLHttpRequest();
        if (!req) {
            return false;
        }
        if (typeof callback != "function") callback = function() {};
        req.onreadystatechange = function() {
            if (req.readyState == 4) {
                return req.status === 200 ? callback(null, req.responseText) : callback(req.status, null);
            }
        };
        req.open("GET", url, true);
        req.send(null);
        return req;
    }
