    function play() {
        console.log("play()");
        dismissNotification();
        if (settings.volume > 0) {
            try {
                BABYLON.Engine.audioEngine.audioContext.resume();
            } catch (e) {
                console.log(e);
            }
        }
        username = document.getElementById("username").value.trim();
        if (username.length == 0) {
            username = randomName();
        }
        document.body.scrollTop = document.documentElement.scrollTop = 0;
        timesPlayed = getStoredNumber("timesPlayed", 0);
        localStorage.setItem("timesPlayed", timesPlayed + 1);
        var lastPreRoll = getStoredNumber("lastPreRoll", 0);
        if (lastPreRoll == 0) {
            lastPreRoll = Date.now();
            localStorage.setItem("lastPreRoll", lastPreRoll);
        }
        if (adTest || Date.now() > lastPreRoll + 3e5 && timesPlayed % 2 == 1) {
            console.log("play() calls PVA");
            playVideoAd();
        } else {
            joinGame();
        }
    }
    var joinResult = null;
    function joinGame() {
        console.log("joinGame()");
        joinResult = null;
        var url;
        var server = selectedServer;
        joinType = CommCode.joinPublicGame;
        var joinGameId = document.getElementById("joinCode").value.trim();
        var mapId = 0;
        autoInvite = false;
        if (document.getElementById("createGame").style.display != "none") {
            joinType = CommCode.createPrivateGame;
            url = getGameServerUrl(servers[server]);
            mapId = document.getElementById("mapSelect").selectedIndex - 1;
            if (mapId < 0) {
                mapId = Math.randomInt(0, minMaps.length);
            } else {
                ga("send", "event", {
                    eventCategory: "Map",
                    eventAction: "Select",
                    eventLabel: minMaps[mapId].name
                });
            }
            autoInvite = true;
        } else if (joinGameId != "") {
            joinType = CommCode.joinPrivateGame;
            if (joinGameId.startsWith("#")) {
                joinGameId = joinGameId.substr(1);
            }
            server = Number.parseInt(joinGameId.substr(0, 1), 36);
            gameId = Number.parseInt(joinGameId.substr(1, 3), 36);
            gameKey = Number.parseInt(joinGameId.substr(4, 2), 36);
            try {
                url = getGameServerUrl(servers[server]);
            } catch (e) {
                console.log("Game not found - Invalid server: " + url + ", " + server);
                openAlertDialog("Game Not Found", "Sorry! This game ID is either<br>invalid, or no longer exists.", {
                    label: "OK"
                });
                gameId = 0;
                gameKey = 0;
                document.getElementById("joinCode").value = "";
                return;
            }
            selectedServer = server;
        } else {
            url = getGameServerUrl(servers[server]);
        }
        showDarkOverlay();
        showSpinner("Connecting", "Please wait!");
        console.log("Connecting to: " + url);
        ws = new WebSocket(url);
        ws.binaryType = "arraybuffer";
        ws.onopen = function(e) {
            console.log("WebSocket opened");
            localStorage.setItem("lastUsername", username);
            ga("send", "event", "play game", "class", classes[playerAccount.classIdx].name);
            fbq("trackCustom", "PlayGame", {
                charClass: classes[playerAccount.classIdx].name,
                server: servers[selectedServer].name
            });
            var len = 16 + username.length * 2;
            if (playerAccount.isLoggedIn) {
                console.log("firebase id and session available");
                len += playerAccount.firebaseId.length * 2 + 5;
            }
            var output = new Comm.output(len);
            output.packInt8(CommCode.joinGame);
            output.packInt8(uuid);
            output.packInt8(joinType);
            output.packInt8(gameType);
            output.packInt8(mapId);
            output.packInt16(gameId);
            output.packInt16(gameKey);
            output.packInt8(playerAccount.classIdx);
            output.packInt8(catalog.get8BitItemId(playerAccount.getPrimaryWeapon(), playerAccount.classIdx));
            output.packInt8(catalog.get8BitItemId(playerAccount.getSecondaryWeapon(), playerAccount.classIdx));
            output.packInt8(playerAccount.colorIdx);
            output.packInt8(catalog.get8BitItemId(playerAccount.hatItem, playerAccount.classIdx));
            output.packInt8(catalog.get8BitItemId(playerAccount.stampItem, playerAccount.classIdx));
            output.packString(username);
            if (playerAccount.isLoggedIn) {
                output.packInt32(playerAccount.session);
                output.packString(playerAccount.firebaseId);
                console.log("firebaseId: " + playerAccount.firebaseId);
            }
            ws.send(output.buffer);
        };
        ws.onclose = function(e) {
            if (freezeFrame) return;
            if (e.code == CloseCode.gameNotFound) {
                console.log("Game not found - id: " + gameId + ", key: " + gameKey);
                openAlertDialog("Game Not Found", "Sorry! This game ID is either<br>invalid, or no longer exists.", {
                    label: "OK"
                });
                gameId = 0;
                gameKey = 0;
                document.getElementById("joinCode").value = "";
            } else if (e.code == CloseCode.gameFull) {
                console.log("Game full - id: " + gameId + ", key: " + gameKey);
                openAlertDialog("Game Full", "Sorry, this game is currently full!<br>Wait a moment, or try another one!", {
                    label: "OK"
                });
            } else if (e.code == CloseCode.badName) {
                closeAlertDialog();
                openAlertDialog("Invalid Name", "I'm going to guess you know why.", {
                    label: "Yes"
                });
                var el = document.getElementById("username");
                el.value = "";
                el.disabled = false;
                el.focus();
                document.getElementById("playButton").disabled = false;
            } else if (e.code == CloseCode.mainMenu) {
                console.log("WebSocket closing - returning to Main Menu");
            } else if (e.code == CloseCode.masterServerBusy) {
                console.log("Master Server busy");
                openAlertDialog("Matchmaker Busy", "Sorry! The match-maker is currently busy serving other players.<br>Please try again in a moment!", {
                    label: "OK"
                });
                gameId = 0;
                gameKey = 0;
                document.getElementById("joinCode").value = "";
            } else if (e.code == CloseCode.masterServerOffline) {
                console.log("Master Server offline");
                openAlertDialog("Matchmaker Offline", "Oops! The match-maker is currently inaccessible.<br>Drop us a line and let us know!", {
                    label: "OK"
                });
                gameId = 0;
                gameKey = 0;
                document.getElementById("joinCode").value = "";
            } else {
                if (inGame) {
                    console.log("Connection lost: " + e.code + " " + e.reason);
                    openAlertDialog("Connection Lost", "Please try a different server,<br>or try again later!", {
                        label: "OK",
                        onclick: reloadPage
                    });
                } else {
                    console.log("Cannot connect: " + e.code + " " + e.reason);
                    var message = "";
                    switch (joinResult) {
                      case CommCode.banned:
                        message = "You are not allowed to join this game.<br><br>Maybe you know why?";
                        break;

                      default:
                        message = 'Please try a different server, reload<br>the page, or try again later!<br><br>Also, visit <a href="http://websocketstest.com" target="_window">websocketstest.com</a> to check for<br>problems with your network and/or system!';
                        break;
                    }
                    openAlertDialog("Cannot Connect", message, {
                        label: "OK",
                        onclick: closeAlertDialog
                    });
                }
            }
        };
        ws.onmessage = function(e) {
            var input = new Comm.input(e.data);
            joinResult = input.unPackInt8U();
            switch (joinResult) {
              case CommCode.gameJoined:
                console.log("CommCode.gameJoined received");
                document.getElementById("mainMenu").style.display = "none";
                teamScore = [ 0, 0, 0 ];
                meId = input.unPackInt8U();
                myTeam = input.unPackInt8U();
                gameType = input.unPackInt8U();
                gameId = input.unPackInt16U();
                gameKey = input.unPackInt16U();
                mapIdx = input.unPackInt8U();
                playerLimit = input.unPackInt8U();
                isGameOwner = input.unPackInt8U() == 1;
                teamScore[1] = input.unPackInt16U();
                teamScore[2] = input.unPackInt16U();
                updateTeamUI();
                isTeamGame = gameType == GameType.teams || gameType == GameType.ctf;
                console.log("is game owner: " + isGameOwner);
                inGame = true;
                startGame();
                break;
            }
        };
    }
    function setVolume(el) {
        settings.volume = el.value;
        localStorage.setItem("volume", settings.volume);
        BABYLON.Engine.audioEngine.setGlobalVolume(settings.volume);
        if (settings.volume == 0) {
            BABYLON.Engine.audioEngine.audioContext.suspend();
        } else {
            BABYLON.Engine.audioEngine.audioContext.resume();
        }
    }
    function setMusicVolume(el) {
        settings.musicVolume = el.value;
        localStorage.setItem("musicVolume", settings.musicVolume);
        if (Music.menu) Music.menu.setVolume(el.value);
        if (Music.game) Music.game.setVolume(el.value);
    }
    function setMouseSensitivity(el) {
        settings.mouseSensitivity = el.value;
        localStorage.setItem("mouseSensitivity", settings.mouseSensitivity);
    }
    function setCheckOption(el) {
        var val = el.checked;
        switch (el.id) {
          case "mouseInvert":
            val = el.checked ? -1 : 1;
            break;

          case "autoDetail":
            if (el.checked) enableAutoDetail(); else disableAutoDetail();
            setDetailSettingsVisibility(el.checked);
            break;

          case "shadowsEnabled":
            if (el.checked) {
                enableShadows();
            } else {
                disableShadows();
            }
            break;

          case "highRes":
            if (el.checked) {
                increaseResolution();
            } else {
                lowerResolution();
            }
            break;

          case "enableChat":
            if (el.checked) {
                enableChat();
            } else {
                disableChat();
            }
            break;
        }
        settings[el.id] = val;
        localStorage.setItem(el.id, val);
    }
    function enableChat() {
        document.getElementById("enableChat").checked = true;
        settings.enableChat = true;
        localStorage.setItem("enableChat", true);
        chatInEl.value = "Press ENTER to chat";
        if (inGame) {
            chatOutEl.style.display = "block";
            chatInEl.style.display = "block";
        }
    }
    function disableChat() {
        settings.enableChat = false;
        localStorage.setItem("enableChat", false);
        if (inGame) {
            chatOutEl.style.display = "none";
            chatInEl.style.display = "none";
        }
    }
    function setDetailSettingsVisibility(invisible) {
        var vis = invisible ? "hidden" : "visible";
        document.getElementById("extraDetails").style.visibility = vis;
        if (!invisible && inGame) {
            settings.shadowsEnabled = gameScene.shadowsEnabled;
            settings.highRes = engine.getHardwareScalingLevel() == 1;
            document.getElementById("shadowsEnabled").checked = settings.shadowsEnabled;
            document.getElementById("highRes").checked = settings.highRes;
            localStorage.setItem("shadowsEnabled", settings.shadowsEnabled ? "true" : "false");
            localStorage.setItem("highRes", settings.highRes ? "true" : "false");
        } else if (inGame) {
            enableShadows();
            increaseResolution();
        }
    }
    function enableAutoDetail() {
        var opt = new BABYLON.SceneOptimizerOptions(40, 4e3);
        var shadowOpt = new BABYLON.SceneOptimization(0);
        shadowOpt.apply = disableShadows;
        opt.optimizations.push(shadowOpt);
        var scalingOpt = new BABYLON.SceneOptimization(1);
        scalingOpt.apply = lowerResolution;
        opt.optimizations.push(scalingOpt);
        if (inGame) {
            optimizer = BABYLON.SceneOptimizer.OptimizeAsync(gameScene, opt);
        }
    }
    function disableAutoDetail() {
        optimizer.stop();
        optimizer.dispose();
        optimizer = null;
    }
    function disableShadows() {
        gameScene.shadowsEnabled = false;
        if (mapMesh && inGame) mapMesh.material = gameScene.getMaterialByName("mapNoShadow");
        return true;
    }
    function enableShadows() {
        gameScene.shadowsEnabled = true;
        if (mapMesh && inGame) mapMesh.material = gameScene.getMaterialByName("map");
    }
    function lowerResolution() {
        engine.setHardwareScalingLevel(2);
        adaptToNewResolution();
        return true;
    }
    function increaseResolution() {
        engine.setHardwareScalingLevel(1);
        adaptToNewResolution();
    }
    function adaptToNewResolution() {
        if (reticle) reticle.resize();
        if (hitIndicator) hitIndicator.resize();
        if (scope && scope.crosshairs.isEnabled()) scope.show();
    }
    function getStoredNumber(name, def) {
        var num = localStorage.getItem(name);
        if (!num) {
            return def;
        }
        return Number(num);
    }
    function getStoredBool(name, def) {
        var str = localStorage.getItem(name);
        if (!str) {
            return def;
        }
        return str == "true" ? true : false;
    }
    function getStoredString(name, def) {
        var str = localStorage.getItem(name);
        if (!str) {
            return def;
        }
        return str;
    }
    function getStoredObject(name, def) {
        var str = localStorage.getItem(name);
        if (!str) {
            return def;
        }
        return JSON.parse(str);
    }
    var alertBarInterval;
    function startAlertBar() {
        var el = document.getElementById("alertFooter");
        el.style.display = "block";
        alertBarInterval = interval.set(function() {
            el.innerText += "-";
            if (el.innerText.length > 10) {
                el.innerText = "-";
            }
        }, 200);
    }
    function openAlertDialog(header, text, button1, button2, bar) {
        hideSpinner();
        showDarkOverlay();
        document.getElementById("alert").style.display = "block";
        document.getElementById("alertHeader").innerHTML = header;
        document.getElementById("alertMessage").innerHTML = text;
        var e = document.getElementById("alertButton1");
        if (button1) {
            e.style.display = "inline-block";
            e.style.visibility = "visible";
            e.innerHTML = button1.label || "OK";
            e.style.width = button1.width || "8em";
            e.style.height = button1.height || "";
            e.onclick = button1.onclick || closeAlertDialog;
        } else {
            e.style.display = "none";
        }
        e = document.getElementById("alertButton2");
        if (button2) {
            e.style.display = "inline-block";
            e.style.visibility = "visible";
            e.innerHTML = button2.label || "Cancel";
            e.style.width = button2.width || "8em";
            e.style.height = button2.height || "";
            e.onclick = button2.onclick || closeAlertDialog;
        } else {
            e.style.display = "none";
        }
        if (bar) {
            startAlertBar();
        } else {
            var el = document.getElementById("alertFooter");
            el.style.display = "none";
            interval.clear(alertBarInterval);
        }
        document.exitPointerLock();
        window.onkeydown = null;
        window.onkeyup = null;
    }
    function closeAlertDialog() {
        document.getElementById("alert").style.display = "none";
        document.getElementById("alertFooter").style.display = "none";
        document.getElementById("username").disabled = false;
        hideDarkOverlay();
        clearInterval(alertBarInterval);
    }
