    function showMainMenu() {
        if (engine) engine.stopRenderLoop();
        document.body.style.overflow = "visible";
        window.scrollY = 0;
        meId = 0;
        viewingPlayerId = 0;
        if (inGame) {
            document.getElementById("menuAdContainer").appendChild(document.getElementById("bannerAdContainer"));
            document.getElementById("inGameAd").style.display = "none;";
            if (me) {
                playerAccount.kills += kills;
                playerAccount.deaths += deaths;
                playerAccount.streak = Math.max(bestOverallStreak, playerAccount.streak);
                updatePlayerStatsDisplay();
            }
            closeAlertDialog();
            interval.clearAll();
            timeout.clearAll();
            fetchTwitchStreams();
            pingServers();
            hideGameDom();
            var oneSignalBell = document.getElementById("onesignal-bell-container");
            if (oneSignalBell) {
                oneSignalBell.style.display = "inline-block";
            }
            if (playerAccount.isLoggedIn && !playerAccount.isUpgraded()) {
                document.getElementById("showBuyPassDialogButton").classList.remove("hideme");
            }
            document.getElementById("upgradeIndicator").classList.remove("ingame");
            ws.close(CloseCode.mainMenu);
            ws = null;
            releaseKeys();
            if (gameStartTime > 0) {
                var timePlayed = Date.now() - gameStartTime;
                ga("send", "timing", "game", "play time", timePlayed);
                fbq("trackCustom", "EndGame", {
                    timePlayed: timePlayed
                });
                if (me && kills > 0) {
                    var ratio = Math.floor(kills / Math.max(kills + deaths, 1) * 100);
                    ga("send", "event", "player stats", "kill ratio", classes[me.charClass].name, ratio);
                    ga("send", "event", "player stats", "best kill streak", classes[me.charClass].name, bestOverallStreak);
                }
            }
            gameScene.dispose();
            inGame = false;
            customizer = new Customizer(function() {
                document.getElementById("mainMenu").style.display = "block";
                showSmallAd();
            });
            extern.customizer = customizer;
        } else {
            document.getElementById("mainMenu").style.display = "block";
        }
    }
    function toggleFullscreen() {
        if (document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement || document.msFullscreenElement) {
            var f = document.exitFullscreen || document.webkitExitFullscreen || document.mozCancelFullScreen || document.msExitFullscreen;
            if (f) f.call(document);
        } else {
            var e = document.body;
            var f = e.requestFullscreen || e.webkitRequestFullscreen || e.mozRequestFullScreen || e.msRequestFullscreen;
            if (f) {
                f.call(e);
                ga("send", "event", "fullscreen");
            }
        }
    }
