    function redeemCode() {
        console.log("redeem code called");
        try {
            var servicesWs = new WebSocket(servicesServer);
        } catch (e) {
            console.log(e);
        }
        var redeemCodeInput = document.getElementById("redeemCodeInput");
        redeemCodeInput.disbled = true;
        var code = redeemCodeInput.value;
        if (!code || code.length == 0) {
            return;
        }
        servicesWs.onopen = function(e) {
            servicesWs.send(JSON.stringify({
                cmd: "redeem",
                uid: playerAccount.firebaseId,
                code: code
            }));
        };
        servicesWs.onmessage = function(e) {
            redeemResult = JSON.parse(e.data);
            if (redeemResult.error) {
                console.log("redeemCode Error: " + JSON.stringify(redeemResult.error));
            } else {
                console.log("redeemCode response: " + redeemResult.result);
                var redeemCodeResultText = document.getElementById("redeemCodeResultText");
                var redeemCodeSuccessButton = document.getElementById("redeemCodeCompleteButton");
                var enterRedeemCode = document.getElementById("enterRedeemCode");
                enterRedeemCode.style.display = "none";
                var redeemCodeResult = document.getElementById("redeemCodeResult");
                redeemCodeResult.style.display = "inline-block";
                switch (redeemResult.result) {
                  case "SUCCESS":
                    redeemCodeResultText.innerHTML = "<h1>CODE CRACKED!!</h1>";
                    if (redeemResult.eggs_given > 0) {
                        if (redeemResult.eggs_given !== undefined && redeemResult.eggs_given !== null && redeemResult.eggs_given > 0) {
                            redeemCodeResultText.innerHTML += '<div style="margin-top: 1em; margin-bottom: 2em; text-align: center;"><img src="img/egg_icon.png" style="width: 2em;" /><h2>+ ' + redeemResult.eggs_given + " </h2></div>";
                            checkBalance();
                        }
                    }
                    var items = [];
                    if (redeemResult.item_ids) {
                        for (var i = 0; i < redeemResult.item_ids.length; i++) {
                            var redeemedItem = catalog.findItemById(redeemResult.item_ids[i]);
                            if (!playerAccount.isItemOwned(redeemedItem)) {
                                playerAccount.inventory.push(redeemedItem);
                            }
                            items.push(redeemedItem);
                        }
                    }
                    customizer.setupItems();
                    if (items.length > 0) {
                        var itemList = createShowItemListHTML(items.length);
                        redeemCodeResultText.innerHTML += itemList.innerHTML;
                        renderItemsInShowItemList(items);
                    }
                    redeemCodeSuccessButton.style = "ssbutton green";
                    break;

                  case "CODE_PREV_REDEEMED":
                    redeemCodeResultText.innerText = "That code has already been used!";
                    redeemCodeSuccessButton.style = "ssbutton red";
                    break;

                  case "CODE_NOT_FOUND":
                    redeemCodeResultText.innerText = "Invalid code";
                    redeemCodeSuccessButton.style = "ssbutton red";
                    break;

                  case "ERROR":
                    console.log("error: " + redeemResult.error);
                    redeemCodeResultText.innerText = "Uh oh, there was problem";
                    redeemCodeSuccessButton.style = "ssbutton red";
                    break;

                  default:
                    redeemCodeResultText.innerText = "Uh oh, there was problem. Try logging in again.";
                    redeemCodeSuccessButton.style = "ssbutton red";
                    break;
                }
            }
            servicesWs.close();
        };
        servicesWs.onclose = function(e) {
            console.log("servicesWs closed: " + e.code + " " + e.reason);
        };
        servicesWs.onerror = function(e) {
            statsEl.innerHTML = '<p style="text-align: left">WebSocket connection failure. Please check your connection at:<br><a href="http://websocketstest.com" target="_window">websocketstest.com</a><br>as well as your firewall and antivirus settings.</p>';
            console.log("servicesWs Error: " + JSON.stringify(e, [ "message", "arguments", "type", "name" ]));
        };
    }
