    function createShowItemListHTML(numItems) {
        var itemContainer = document.getElementById("showItemContainer").cloneNode(true);
        var itemList = itemContainer.querySelector("#showItemList");
        for (var i = 0; i < numItems; i++) {
            var appendIndexToId = function(element) {
                element.id += "_" + i;
            };
            var itemTemplate = document.getElementById("showItemTemplate").cloneNode(true);
            appendIndexToId(itemTemplate);
            var itemCanvas = itemTemplate.querySelector("#showItemCanvas");
            appendIndexToId(itemCanvas);
            var itemName = itemTemplate.querySelector("#showItemName");
            appendIndexToId(itemName);
            if (numItems > 1) {
                itemTemplate.style.float = "left";
            }
            if (i > 0) {
                itemTemplate.classList.add("showItemTemplateLeft");
            }
            itemList.appendChild(itemTemplate);
        }
        itemContainer.class = "";
        return itemContainer;
    }
    function renderItemsInShowItemList(items) {
        for (var i = 0; i < items.length; i++) {
            var itemCanvas = document.getElementById("showItemCanvas_" + i);
            items[i].renderToCanvas(itemCanvas);
            var itemName = document.getElementById("showItemName_" + i);
            itemName.innerHTML = items[i].name;
        }
    }
    function callApi(apiRequest, successCallback, errorCallback, closeCallback) {
        console.log(apiRequest.cmd + " called");
        try {
            var servicesWs = new WebSocket(servicesServer);
        } catch (e) {
            console.log(e);
        }
        servicesWs.onopen = function(e) {
            servicesWs.send(JSON.stringify(apiRequest));
            console.log("servicesWs opened, and " + apiRequest.cmd + " request sent");
        };
        servicesWs.onmessage = function(e) {
            var response = null;
            try {
                response = JSON.parse(e.data);
            } catch (e) {
                console.log("Invalid data returned from services API");
                errorCallback();
                return;
            }
            if (response.error) {
                console.log(apiRequest.cmd + " error: " + JSON.stringify(response.error));
                errorCallback(response);
            } else {
                successCallback(response);
            }
            servicesWs.close();
        };
        servicesWs.onclose = function(e) {
            console.log(apiRequest.cmd + " servicesWs closed: " + e.code + " " + e.reason);
            if (closeCallback) {
                closeCallback();
            }
        };
        servicesWs.onerror = function(e) {
            errorCallback();
        };
    }
    function getLocText(stringId) {
        return language[stringId][currentLanguage];
    }
    var playerAccount = new PlayerAccount();
    function PlayerAccount() {
        this.loggedOut = function() {
            this.firebaseId = null;
            this.session = null;
            this.kills = 0;
            this.deaths = 0;
            this.streak = 0;
            this.currentBalance = 0;
            this.classIdx = 0;
            this.inventory = [];
            this.pickedWeapons = [];
            this.stampItem = null;
            this.hatItem = null;
            this.colorIdx = 0;
            this.isLoggedIn = false;
            this.killMultiplier = 1;
            this.hideAds = false;
            this.upgradeExpiryDate = null;
            this.upgradeIsExpired = false;
            this.maybeSchoolEmail = false;
            for (var cIdx = 0; cIdx < CharClass.length; cIdx++) {
                var defaultPicks = [ catalog.forClass[cIdx].primaryWeapons[0], catalog.forClass[cIdx].secondaryWeapons[0] ];
                this.pickedWeapons.push(defaultPicks);
            }
        };
        this.setClass = function(classIdx) {
            this.classIdx = classIdx;
        };
        this.pickWeapon = function(slot, weaponItem) {
            var foundInList = catalog.findItemInListById(weaponItem, catalog.forClass[this.classIdx].forWeaponSlot[slot]);
            if (foundInList === false) {
                weaponItem = catalog.forClass[this.classIdx].forWeaponSlot[slot][0];
            }
            this.pickedWeapons[this.classIdx][slot] = weaponItem;
        };
        this.getPickedWeaponInSlot = function(slot) {
            return this.pickedWeapons[this.classIdx][slot];
        };
        this.getPrimaryWeapon = function() {
            return this.getPickedWeaponInSlot(Slot.Primary);
        };
        this.getSecondaryWeapon = function() {
            return this.getPickedWeaponInSlot(Slot.Secondary);
        };
        this.isUpgraded = function() {
            return this.upgradeProductId !== undefined && this.upgradeProductId !== null && this.upgradeIsExpired === false;
        };
        this.isItemOwned = function(item) {
            for (var i = 0; i < this.inventory.length; i++) {
                if (this.inventory[i] && this.inventory[i].id === item.id) {
                    return true;
                }
            }
            return false;
        };
        this.getEquippedItems = function() {
            var equippedItems = [ this.getPrimaryWeapon(), this.getSecondaryWeapon() ];
            if (this.hatItem !== null) {
                equippedItems.push(this.hatItem);
            }
            if (this.stampItem !== null) {
                equippedItems.push(this.stampItem);
            }
            return equippedItems;
        };
        this.isItemEquipped = function(item) {
            if (item === null) {
                return false;
            }
            var foundItem = catalog.findItemInListById(item.id, this.getEquippedItems());
            return foundItem !== null;
        };
        this.loggedIn = function(accountData) {
            var hasValue = function(a) {
                return a !== undefined && a !== null && a !== 0;
            };
            this.firebaseId = accountData.firebaseId;
            this.session = accountData.session;
            this.kills = accountData.kills;
            this.deaths = accountData.deaths;
            this.streak = accountData.streak;
            this.currentBalance = accountData.currentBalance;
            this.ownedItemIds = accountData.ownedItemIds;
            this.upgradeProductId = accountData.upgradeProductId;
            this.killMultiplier = hasValue(accountData.upgradeMultiplier) ? accountData.upgradeMultiplier : 1;
            this.hideAds = hasValue(accountData.upgradeAdFree) ? accountData.upgradeAdFree : false;
            this.upgradeExpiryDate = hasValue(accountData.upgradeExpiryDate) ? accountData.upgradeExpiryDate : null;
            this.upgradeIsExpired = hasValue(accountData.upgradeExpiryDate) ? accountData.upgradeIsExpired : null;
            this.maybeSchoolEmail = accountData.maybeSchoolEmail;
            var version = accountData.version === undefined || accountData.version === null ? 1 : accountData.version;
            if (version >= 1) {
                if (accountData.loadout !== undefined && accountData.loadout !== null) {
                    if (accountData.loadout.classIdx !== undefined && accountData.loadout.classIdx !== null) {
                        this.setClass(accountData.loadout.classIdx);
                    }
                    var outer = this;
                    var trySetPickedWeapon = function(weaponId, classIdx, slot) {
                        var weaponItem = catalog.forClass[classIdx].forWeaponSlot[slot][0];
                        if (hasValue(weaponId)) {
                            weaponItem = catalog.findItemById(weaponId);
                        }
                        outer.pickedWeapons[classIdx][slot] = weaponItem;
                    };
                    for (var c = 0; c < CharClass.length; c++) {
                        trySetPickedWeapon(accountData.loadout.primaryId[c], c, Slot.Primary);
                        trySetPickedWeapon(accountData.loadout.secondaryId[c], c, Slot.Secondary);
                    }
                    if (hasValue(accountData.loadout.hatId)) {
                        var hatItem = catalog.findItemById(accountData.loadout.hatId);
                        this.hatItem = hatItem;
                    }
                    if (hasValue(accountData.loadout.stampId)) {
                        var stampItem = catalog.findItemById(accountData.loadout.stampId);
                        this.stampItem = stampItem;
                    }
                    if (hasValue(accountData.loadout.colorIdx)) {
                        this.colorIdx = accountData.loadout.colorIdx;
                        if (this.colorIdx >= 7 && this.isUpgraded() === false) {
                            this.colorIdx = 0;
                        }
                    }
                }
                if (hasValue(accountData.ownedItemIds)) {
                    for (var i = 0; i < accountData.ownedItemIds.length; i++) {
                        var item = catalog.findItemById(accountData.ownedItemIds[i]);
                        this.inventory.push(item);
                    }
                }
            }
            this.isLoggedIn = true;
        };
        this.setUpgrade = function(getUpgradeData) {
            this.upgradeProductId = getUpgradeData.upgradeProductId;
            this.multiplier = getUpgradeData.multiplier;
            this.hideAds = getUpgradeData.hideAds;
            this.upgradeIsExpired = getUpgradeData.isExpired;
            if (this.colorIdx >= 7 && this.isUpgraded() === false) {
                this.colorIdx = 0;
            }
        };
        this.syncToServer = function() {
            try {
                var servicesWs = new WebSocket(servicesServer);
            } catch (e) {
                console.log(e);
            }
            var updateHatId = playerAccount.hatItem !== undefined && playerAccount.hatItem !== null ? playerAccount.hatItem.id : null;
            var updateStampId = playerAccount.stampItem !== undefined && playerAccount.stampItem !== null ? playerAccount.stampItem.id : null;
            var loadout = {
                cmd: "saveEquip",
                dbId: this.firebaseId,
                class_idx: this.classIdx,
                soldier_primary_item_id: this.pickedWeapons[CharClass.Soldier][Slot.Primary].id,
                soldier_secondary_item_id: this.pickedWeapons[CharClass.Soldier][Slot.Secondary].id,
                scrambler_primary_item_id: this.pickedWeapons[CharClass.Scrambler][Slot.Primary].id,
                scrambler_secondary_item_id: this.pickedWeapons[CharClass.Scrambler][Slot.Secondary].id,
                ranger_primary_item_id: this.pickedWeapons[CharClass.Ranger][Slot.Primary].id,
                ranger_secondary_item_id: this.pickedWeapons[CharClass.Ranger][Slot.Secondary].id,
                eggsploder_primary_item_id: this.pickedWeapons[CharClass.Eggsploder][Slot.Primary].id,
                eggsploder_secondary_item_id: this.pickedWeapons[CharClass.Eggsploder][Slot.Secondary].id,
                hat_id: updateHatId,
                stamp_id: updateStampId,
                color: this.colorIdx,
                save: typeof checkStatus !== "undefined" ? checkStatus() : true
            };
            var json = JSON.stringify(loadout);
            servicesWs.onopen = function(e) {
                servicesWs.send(json);
                console.log("servicesWs opened, and saveEquip request sent");
            };
            servicesWs.onmessage = function(e) {
                responseData = JSON.parse(e.data);
                if (responseData.error) {
                    console.log("SyncToServer Error: " + JSON.stringify(responseData.error));
                } else {
                    console.log("SyncToServer completed successfully");
                }
                servicesWs.close();
            };
            servicesWs.onclose = function(e) {
                console.log("servicesWs closed: " + e.code + " " + e.reason);
            };
            servicesWs.onerror = function(e) {
                console.log("servicesWs Error: " + JSON.stringify(e, [ "message", "arguments", "type", "name" ]));
            };
        };
        this.loggedOut();
    }
    "use strict";
    var shake;
    function PlayerActor(player) {
        this.player = player;
        this.scene = player.scene;
        this.mesh = new BABYLON.TransformNode();
        this.hat = null;
        var hatItem = player.hatItem;
        var stampItem = player.stampItem;
        this.bodyMesh = this.scene.cloneMesh("egg", this.mesh);
        this.bodyMesh.position.y = .32;
        this.bodyMesh.player = this.player;
        this.bodyMesh.material = this.scene.getMaterialByName("eggShell");
        this.bodyMesh.material.setTexture("textureSampler", stampTexture);
        this.head = new BABYLON.TransformNode();
        this.head.parent = this.mesh;
        this.head.position.y = .3;
        this.head.position.z = 0;
        this.gunContainer = new BABYLON.TransformNode();
        this.gunContainer.parent = this.head;
        this.gunContainer.rotation.y = -.14;
        this.gunContainer.rotation.x = -.035;
        this.setupStowAnims();
        this.eye = new BABYLON.TransformNode();
        this.eye.position.y = .1;
        this.eye.position.x = 0;
        this.eye.parent = this.head;
        this.hands = this.scene.cloneMesh("hands", this.gunContainer);
        this.hands.skeleton = this.scene.cloneSkeleton("hands_skeleton");
        this.hands.material = this.scene.getMaterialByName("standard");
        this.gripBone = this.hands.skeleton.bones[this.hands.skeleton.getBoneIndexByName("gripHand")];
        this.foreBone = this.hands.skeleton.bones[this.hands.skeleton.getBoneIndexByName("foreHand")];
        this.bodyMesh.overlayColor = BABYLON.Color3.Green();
        this.hands.overlayColor = BABYLON.Color3.Green();
        if (this.player.shield > 0) {
            this.bodyMesh.renderOverlay = true;
            this.hands.renderOverlay = true;
        }
        this.setShellColor(this.player.shellColor);
        shake = 0;
        if (shadowGen) shadowGen.getShadowMap().renderList.push(this.bodyMesh);
        if (inGame) {
            if (this.player.id == meId) {
                this.hands.setRenderingGroupId(2);
            } else {
                this.setupNameSprite();
                this.showNameSprite();
            }
            if (inGame) this.updateTeam();
        } else {
            this.bodyMesh.outlineColor = teamColors.outline[0].clone();
            this.bodyMesh.outlineColor.a = 0;
        }
        this.mesh.position.x = this.player.x;
        this.mesh.position.y = this.player.y;
        this.mesh.position.z = this.player.z;
        if (this.player.id != meId) {
            this.wearHat(this.player.hatItem);
            this.applyStamp(this.player.stampItem);
        }
        if (playOffline) {
            this.hands.setEnabled(false);
        }
        this.bobbleIntensity = 0;
        this.scope = false;
        this.zoomed = false;
        this.hitSoundDelay = 0;
    }
    PlayerActor.prototype.wearHat = function(hatItem) {
        this.removeHat();
        if (hatItem !== null) {
            this.hat = this.scene.cloneMesh(hatItem.item_data.meshName, this.bodyMesh);
            this.hat.position.y = -.02;
        }
    };
    PlayerActor.prototype.removeHat = function() {
        if (this.hat !== undefined && this.hat !== null) {
            this.hat.dispose();
        }
    };
    PlayerActor.prototype.applyStamp = function(stampItem) {
        this.removeStamp();
        if (stampItem !== null) {
            this.bodyMesh.stampU = stampItem.item_data.x / 16;
            this.bodyMesh.stampV = 1 - stampItem.item_data.y / 16;
        }
    };
    PlayerActor.prototype.removeStamp = function() {
        this.bodyMesh.stampU = 0;
        this.bodyMesh.stampV = 1;
    };
    PlayerActor.prototype.drawTextOnNameTexture = function(text, x, y, size, color, center) {
        var shadowCoords = [ {
            x: 0,
            y: -4
        }, {
            x: -4,
            y: 0
        }, {
            x: 4,
            y: 0
        }, {
            x: 0,
            y: 4
        } ];
        var coords = [ {
            x: 0,
            y: -1
        }, {
            x: -1,
            y: 0
        }, {
            x: 1,
            y: 0
        }, {
            x: 0,
            y: 1
        } ];
        var tx = this.player.id % 4 * 512;
        var ty = 2048 - Math.floor(this.player.id / 4) * 256;
        x += tx;
        y = -y + ty;
        if (center) {
            x += 256 - getFloatingNameWidth(text, size) / 2;
        }
        for (var i = 0; i < 4; i++) {
            nameTexture.drawText(text, x + shadowCoords[i].x, y + shadowCoords[i].y, "bold " + size + "px Nunito, sans-serif", "rgba(0, 0, 0, 0.5)", "transparent");
        }
        for (var i = 0; i < 4; i++) {
            nameTexture.drawText(text, x + coords[i].x, y + coords[i].y, "bold " + size + "px Nunito, sans-serif", color, "transparent");
        }
    };
    PlayerActor.prototype.setupNameSprite = function() {
        var tx = this.player.id % 4 * 512;
        var ty = 2048 - Math.floor(this.player.id / 4) * 256;
        nameTexture.clearRect(tx, ty - 256, 512, 256);
        this.drawTextOnNameTexture(this.player.name, 0, 32, 60, "white", true);
    };
    PlayerActor.prototype.updateTeam = function() {
        if (this.player.id == meId) {} else if (this.player.team > 0) {
            if (this.player.team == myTeam) {
                this.bodyMesh.outlineColor = teamColors.outline[this.player.team].clone();
            } else {
                this.bodyMesh.outlineColor.a = 0;
            }
            if (this.nameSprite) {
                this.nameSprite.width = .6;
                this.nameSprite.height = .3;
                this.nameSprite.color = teamColors.outline[this.player.team];
            }
        } else {
            this.bodyMesh.outlineColor.a = 0;
        }
    };
    PlayerActor.prototype.update = function(delta) {
        var bcos = Math.cos(this.player.bobble) * this.bobbleIntensity;
        var bsina = Math.abs(Math.sin(this.player.bobble) * this.bobbleIntensity);
        var bsin = Math.sin(this.player.bobble * 2) * this.bobbleIntensity;
        if (this.player.shield > 0) {
            var alpha = Math.random() * .7 + .2;
            this.bodyMesh.overlayAlpha = alpha;
            this.hands.overlayAlpha = alpha;
        }
        if (this.player.id == meId) {
            if (this.scope && this.player.isAtReady(true)) {
                camera.fov = camera.fov + (this.player.weapon.actor.scopeFov - camera.fov) / 3;
                this.gunContainer.rotation.y *= .667;
                this.gunContainer.rotation.x *= .667;
                this.gunContainer.position.x += (-.25 - this.gunContainer.position.x) / 3;
                this.gunContainer.position.y += (this.player.weapon.actor.scopeY - this.gunContainer.position.y) / 4;
                this.gunContainer.position.z += (-.05 - this.gunContainer.position.z) / 3;
                if (this.player.weapon.hasScope && !this.zoomed && camera.fov < this.player.weapon.actor.scopeFov + .05) {
                    scope.show();
                    this.gunContainer.setEnabled(false);
                    this.zoomed = true;
                }
            } else {
                camera.fov = camera.fov + (1.25 - camera.fov) / 3;
                this.gunContainer.rotation.y += (-.14 + bcos * 2 - this.gunContainer.rotation.y) / 3;
                this.gunContainer.rotation.x += (-.035 + bsin * .75 - this.gunContainer.rotation.x) / 3;
                this.gunContainer.position.x *= .667;
                this.gunContainer.position.y *= .667;
                this.gunContainer.position.z *= .667;
                if (this.zoomed && camera.fov > this.player.weapon.actor.scopeFov + .05) {
                    scope.hide();
                    this.gunContainer.setEnabled(true);
                    this.zoomed = false;
                }
            }
        } else {
            this.gunContainer.rotation.y += (-.14 + bcos * 2 - this.gunContainer.rotation.y) / 3;
            this.gunContainer.rotation.x += (-.035 + bsin * .75 - this.gunContainer.rotation.x) / 3;
            if (this.player.team > 0 && this.player.team == myTeam && this.nameSprite) {
                var dist = Math.length3(this.player.x - me.x, this.player.y - me.y, this.player.z - me.z);
                var fac = Math.pow(dist, 1.25);
                this.nameSprite.width = fac / 10 + .6;
                this.nameSprite.height = fac / 20 + .3;
            }
        }
        var dx = this.player.x - this.mesh.position.x;
        var dy = this.player.y - this.mesh.position.y;
        var dz = this.player.z - this.mesh.position.z;
        var dist = Math.length3(dx, dy, dz);
        if (this.player.id == meId) {
            this.mesh.position.x += dx / 2;
            this.mesh.position.y += dy / 2;
            this.mesh.position.z += dz / 2;
        } else {
            this.mesh.position.x += dx / 6;
            this.mesh.position.y += dy / 2;
            this.mesh.position.z += dz / 6;
        }
        var diffYaw = Math.radDifference(this.player.yaw, this.mesh.rotation.y);
        var diffPitch = Math.radDifference(this.player.pitch, this.head.rotation.x);
        this.mesh.rotation.y = this.player.yaw;
        this.head.rotation.x = this.player.pitch;
        this.bodyMesh.rotation.x = this.head.rotation.x / 4;
        var bobbleTarget;
        if (this.player.jumping) {
            bobbleTarget = 0;
        } else {
            bobbleTarget = Math.length3(this.player.dx, this.player.dy, this.player.dz);
        }
        this.bobbleIntensity += (bobbleTarget - this.bobbleIntensity) / 10;
        this.bodyMesh.rotation.z = bcos * 5;
        this.bodyMesh.position.y = bsina * 1.5 + .32;
        if (shake > 0) {
            shake *= .9;
            if (shake < .001) {
                shake = 0;
            } else {
                var x = Math.random() * shake - shake * .5;
                var y = Math.random() * shake - shake * .5;
                var z = Math.random() * shake - shake * .5;
                this.eye.rotation.x += (x - this.eye.rotation.x) / 10;
                this.eye.rotation.y += (y - this.eye.rotation.y) / 10;
                this.eye.rotation.z += (z - this.eye.rotation.z) / 10;
            }
        } else {
            this.eye.rotation.x *= .9;
            this.eye.rotation.y *= .9;
            this.eye.rotation.z *= .9;
        }
        if (this.player.id != meId) {
            var visible = isMeshVisible(this.mesh, .31);
            this.mesh.setVisible(visible);
            if (visible) {
                this.showNameSprite();
            } else {
                this.hideNameSprite();
            }
            if (this.nameSprite) {
                this.positionNameSprite();
            }
        }
        this.hitSoundDelay = Math.max(this.hitSoundDelay - delta, 0);
    };
    PlayerActor.prototype.positionNameSprite = function() {
        if (this.nameSprite) {
            var mp = this.mesh.position.clone();
            mp.y += this.nameSprite.height * .5 + .65;
            var v = new BABYLON.Vector3(camera.globalPosition.x - mp.x, camera.globalPosition.y - mp.y, camera.globalPosition.z - mp.z).normalize();
            v.scaleInPlace(.4);
            v.addInPlace(mp);
            this.nameSprite.position = v;
        }
    };
    PlayerActor.prototype.showNameSprite = function() {
        if (this.player.playing && !this.nameSprite) {
            this.nameSprite = new BABYLON.Sprite("", nameSprites);
            this.nameSprite.invertV = true;
            this.nameSprite.width = .6;
            this.nameSprite.height = .3;
            this.nameSprite.cellIndex = this.player.id;
            this.nameSprite.color = teamColors.outline[this.player.team];
        }
    };
    PlayerActor.prototype.hideNameSprite = function() {
        if (this.nameSprite) {
            this.nameSprite.dispose();
            this.nameSprite = null;
        }
    };
    PlayerActor.prototype.scopeIn = function() {
        this.scope = true;
    };
    PlayerActor.prototype.scopeOut = function() {
        this.scope = false;
    };
    PlayerActor.prototype.hit = function() {
        if (this.hitSoundDelay <= 0) {
            Sounds.hit.play(this.bodyMesh.absolutePosition);
            this.hitSoundDelay = 10;
        }
    };
    PlayerActor.prototype.removeFromPlay = function() {
        this.scope = false;
        this.zoomed = false;
        this.throwingGrenade = false;
        this.gripBone._frozen = false;
        this.mesh.setEnabled(false);
        this.hideNameSprite();
    };
    PlayerActor.prototype.restoreToPlay = function() {
        this.mesh.setEnabled(true);
        this.gunContainer.setEnabled(true);
        if (this.player.id != meId) this.showNameSprite();
    };
    PlayerActor.prototype.remove = function() {
        this.mesh.dispose();
        this.hideNameSprite();
    };
    PlayerActor.prototype.fire = function() {
        if (this.zoomed && this.player.weapon.hasScope) {
            shake = .25;
            this.eye.rotation.x = -.1;
        }
    };
    PlayerActor.prototype.reachForGrenade = function() {
        var that = this;
        this.throwingGrenade = true;
        this.gripBone._frozen = true;
        this.hands.skeleton.enableBlending(.2);
        this.hands.skeleton.beginAnimation("grenade_grab", false, 1, function() {
            if (that.hands.skeleton) that.hands.skeleton.disableBlending();
        });
    };
    PlayerActor.prototype.throwGrenade = function() {
        var that = this;
        if (this.player.id == meId) {
            document.getElementById("grenadeThrowContainer").style.visibility = "hidden";
        }
        this.hands.skeleton.beginAnimation("grenade_throw", false, 1, function() {
            if (that.hands.skeleton) {
                that.throwingGrenade = false;
                that.gripBone._frozen = false;
            }
        });
    };
    PlayerActor.prototype.setShellColor = function(colorIdx) {
        if (colorIdx < 0 || colorIdx >= shellColors.length) {
            console.log("Shell color out of bounds: " + colorIdx);
            colorIdx = 0;
        }
        var color = BABYLON.Color3.FromHexString(shellColors[colorIdx]);
        this.bodyMesh.colorMult = color;
        this.hands.colorMult = color;
    };
    PlayerActor.prototype.setWeaponSkeleton = function(skeleton) {
        this.skeleton = skeleton;
        this.weaponGripBone = this.skeleton.bones[this.skeleton.getBoneIndexByName("gripHand")];
        this.weaponForeBone = this.skeleton.bones[this.skeleton.getBoneIndexByName("foreHand")];
    };
    PlayerActor.prototype.handsToWeaponSkeleton = function() {
        this.gripBone.position = this.weaponGripBone.position;
        this.gripBone.setRotationQuaternion(this.weaponGripBone.rotationQuaternion);
        if (this.throwingGrenade == true) return;
        this.foreBone.position = this.weaponForeBone.position;
        this.foreBone.setRotationQuaternion(this.weaponForeBone.rotationQuaternion);
    };
    PlayerActor.prototype.setupStowAnims = function() {
        var gunRotationAnimation = new BABYLON.Animation("", "rotation", 60, BABYLON.Animation.ANIMATIONTYPE_VECTOR3, BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT);
        var gunScaleAnimation = new BABYLON.Animation("", "scaling", 60, BABYLON.Animation.ANIMATIONTYPE_VECTOR3, BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT);
        var gunPositionAnimation = new BABYLON.Animation("", "position", 60, BABYLON.Animation.ANIMATIONTYPE_VECTOR3, BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT);
        var gunRotationEase = new BABYLON.CubicEase();
        gunRotationEase.setEasingMode(BABYLON.EasingFunction.EASINGMODE_EASEINOUT);
        gunRotationAnimation.setEasingFunction(gunRotationEase);
        var gunScaleEase = new BABYLON.CubicEase();
        gunScaleEase.setEasingMode(BABYLON.EasingFunction.EASINGMODE_EASEINOUT);
        gunScaleAnimation.setEasingFunction(gunScaleEase);
        var gunPositionEase = new BABYLON.CubicEase();
        gunPositionEase.setEasingMode(BABYLON.EasingFunction.EASINGMODE_EASEINOUT);
        gunPositionAnimation.setEasingFunction(gunPositionEase);
        var gunRotationKeys = [ {
            frame: 0,
            value: new BABYLON.Vector3(-.035, -.14, 0)
        }, {
            frame: 25,
            value: new BABYLON.Vector3(1, -1.5, 0)
        }, {
            frame: 30,
            value: new BABYLON.Vector3(-1, -1.5, 0)
        }, {
            frame: 55,
            value: new BABYLON.Vector3(-.035, -.14, 0)
        } ];
        var gunScaleKeys = [ {
            frame: 0,
            value: new BABYLON.Vector3(1, 1, 1)
        }, {
            frame: 25,
            value: new BABYLON.Vector3(.25, .25, .25)
        }, {
            frame: 30,
            value: new BABYLON.Vector3(.25, .25, .25)
        }, {
            frame: 55,
            value: new BABYLON.Vector3(1, 1, 1)
        } ];
        var gunPositionKeys = [ {
            frame: 0,
            value: new BABYLON.Vector3(0, 0, 0)
        }, {
            frame: 25,
            value: new BABYLON.Vector3(.1, .1, -.2)
        }, {
            frame: 30,
            value: new BABYLON.Vector3(.1, 0, -.2)
        }, {
            frame: 55,
            value: new BABYLON.Vector3(0, 0, 0)
        } ];
        gunRotationAnimation.setKeys(gunRotationKeys);
        gunScaleAnimation.setKeys(gunScaleKeys);
        gunPositionAnimation.setKeys(gunPositionKeys);
        this.gunContainer.animations.push(gunRotationAnimation);
        this.gunContainer.animations.push(gunScaleAnimation);
        this.gunContainer.animations.push(gunPositionAnimation);
    };
    "use strict";
    function RocketActor(rocket) {
        this.rocket = rocket;
        this.scene = rocket.scene;
        this.armed = false;
        this.delayFrames = 0;
        this.mesh = this.scene.getMeshByName("rocket").createInstance("");
        this.mesh.setEnabled(false);
    }
    RocketActor.prototype.fire = function() {
        this.armed = false;
        if (this.rocket.player.id == meId) {
            this.delayFrames = Math.ceil(ping / 17) + 3;
        } else {
            this.delayFrames = 3;
        }
        this.mesh.position.x = this.rocket.x;
        this.mesh.position.y = this.rocket.y;
        this.mesh.position.z = this.rocket.z;
        this.mesh.lookAt(new BABYLON.Vector3(this.rocket.x + this.rocket.dx, this.rocket.y + this.rocket.dy, this.rocket.z + this.rocket.dz));
        this.mesh.rotation.x += .015;
        this.mesh.rotation.y -= .015;
    };
    RocketActor.prototype.update = function() {
        if (--this.delayFrames <= 0) {
            this.mesh.setEnabled(true);
        }
        if (!this.armed && this.rocket.minRange <= 0) {
            this.armed = true;
            Sounds.rpegg.fly.play(this.mesh, true);
        }
        if (this.delayFrames % 2 == 0) {
            var size = .4;
            var dx = Math.random() * .04 - .02;
            var dy = Math.random() * .04 - .02;
            var dz = Math.random() * .04 - .02;
            if (this.armed) {
                addExplosionSprite(explosionSmokeManager, 30, this.rocket.x, this.rocket.y, this.rocket.z, dx, dy, dz, size, false);
                addExplosionSprite(explosionFireManager, 10, this.rocket.x, this.rocket.y, this.rocket.z, dx, dy, dz, size, false);
            }
        }
        this.mesh.position.x = this.rocket.x;
        this.mesh.position.y = this.rocket.y;
        this.mesh.position.z = this.rocket.z;
    };
    RocketActor.prototype.remove = function() {
        this.mesh.setEnabled(false);
    };
    BABYLON.Effect.ShadersStore["standardVertexShader"] = "\n#include<instancesDeclaration>\n#include<bonesDeclaration>\n\nprecision lowp float;\n\n// Attributes\nattribute vec3 position;\nattribute vec3 normal;\nattribute vec4 color;\nattribute vec2 uv;\n\n// Uniforms\nuniform mat4 view;\nuniform mat4 viewProjection;\nuniform mat4 shadowLightMat;\nuniform vec3 cameraPosition;\nuniform vec3 colorMult;\n\n// Varying\nvarying vec4 vPositionFromLight;\nvarying vec3 vPositionFromCamera;\nvarying vec3 vNormal;\nvarying vec4 vColor;\nvarying vec4 vEmissiveColor;\nvarying float fFogDistance;\n\n#ifdef EGGSHELL\n\tvarying vec2 vUV;\n#endif\n\nfloat random(vec3 p)\n{\n    vec3 K1 = vec3(23.14069263277926, 2.665144142690225, 8.2318798443);\n    return fract(cos(dot(p, K1)) * 12345.6789);\n}\n\n// MAIN\nvoid main(void) {\n\t#include<instancesVertex>\n\t#include<bonesVertex>\n\tvec4 worldPosition = finalWorld * vec4(position, 1.);\n\n\t#ifdef RECEIVESHADOWS\n\t\tvPositionFromLight = shadowLightMat * worldPosition;\n\t#endif\n\n\tvNormal = normalize(vec3(finalWorld * vec4(normal, 0.0)));\n\tvColor = color;\n\t\n\t#ifdef COLORMULT\n\t\tvColor.rgb *= colorMult;\n\t#endif\n\n\t#ifdef DIRT\n\t\tvColor.rgb *= random(floor(worldPosition.xyz + vec3(0.5, 0.5, 0.5))) * 0.2 + 0.7;\n\t#endif\n\n\tfFogDistance = (view * worldPosition).z;\n\tgl_Position = viewProjection * worldPosition;\n\n\t#ifdef EGGSHELL\n\t\tvUV = uv;\n\t\tvPositionFromCamera = normalize(cameraPosition - worldPosition.xyz);\n\t#endif\n}\n";
    BABYLON.Effect.ShadersStore["standardPixelShader"] = "\n#define FOGMODE_NONE 0.\n#define FOGMODE_EXP 1.\n#define FOGMODE_EXP2 2.\n#define FOGMODE_LINEAR 3.\n#define E 2.71828\n\nprecision lowp float;\n\n// Uniforms\nuniform sampler2D shadowSampler;\nuniform vec3 shadowParams;\nuniform vec4 vFogInfos;\nuniform vec3 vFogColor;\nuniform vec3 emissiveColor;\nuniform mat4 worldView;\nuniform float hp;\nuniform vec3 colorMult;\nuniform vec4 outlineColor;\nuniform sampler2D textureSampler;\nuniform vec2 stampOffset;\n\n// Varying\nvarying vec4 vPositionFromLight;\nvarying vec3 vPositionFromCamera;\nvarying vec4 vColor;\nvarying vec2 vUV;\nvarying vec3 vNormal;\nvarying float fFogDistance;\n\nconst float sOff = .001;\n\n// FUNCTIONS\nfloat unpack(vec4 color)\n{\n\tconst vec4 bit_shift = vec4(1.0 / (255.0 * 255.0 * 255.0), 1.0 / (255.0 * 255.0), 1.0 / 255.0, 1.0);\n\treturn dot(color, bit_shift);\n}\n\nfloat random(vec2 p)\n{\n    vec2 K1 = vec2(23.14069263277926, 2.665144142690225);\n    return fract(cos(dot(p, K1)) * 12345.6789);\n}\n\nfloat calcFogFactor()\n{\n\tfloat fogCoeff = 1.0;\n\tfloat fogStart = vFogInfos.y;\n\tfloat fogEnd = vFogInfos.z;\n\tfloat fogDensity = vFogInfos.w;\n\n\tfogCoeff = 1.0 / pow(E, fFogDistance * fFogDistance * fogDensity * fogDensity * 4.); // Exp2\n\n\treturn clamp(fogCoeff, 0.0, 1.0);\n}\n\nfloat computeShadow(vec4 vPositionFromLight, sampler2D shadowSampler, float darkness)\n{\n\tvec3 depth = vPositionFromLight.xyz / vPositionFromLight.w;\n\tdepth = 0.5 * depth + vec3(0.5);\n\tvec2 uv = depth.xy;\n\n\tif (uv.x < 0. || uv.x > 1.0 || uv.y < 0. || uv.y > 1.0)\n\t{\n\t\treturn 1.0;\n\t}\n\n\t#ifndef SHADOWFULLFLOAT\n\t\tfloat shadow = unpack(texture2D(shadowSampler, uv));\n\t#else\n\t\tfloat shadow = texture2D(shadowSampler, uv).x;\n\t#endif\n\n\tif (depth.z < shadow) return 1.;\n\tfloat s = clamp((depth.z - shadow) * 12. + 0.5, 0.5, 1.0);\n\treturn min(1.0, max(s, length(vPositionFromLight.xy)));\n}\n\nvec3 desaturate(vec3 color, float amount)\n{\n    vec3 gray = vec3(dot(vec3(0.2126,0.7152,0.0722), color));\n    return vec3(mix(color, gray, amount));\n}\n\n// MAIN\nvoid main(void)\n{\n\tvec4 color = vColor;\n\n\t#ifdef EGGSHELL // Show cracks and stamp texture!\n\t\tcolor.rgb = min((color.rgb - 0.5) * 4. + hp + 2., 1.);\n\t\tcolor.rgb *= colorMult;\n\t\tvec2 uv = clamp(vUV, vec2(0., 0.9375), vec2(.0625, 1.));\n\t\tuv += stampOffset;\n\t\tcolor.rgb = mix(color.rgb, texture2D(textureSampler, uv).rgb, texture2D(textureSampler, uv).a);\n\t#endif\n\n\t#ifdef RECEIVESHADOWS\n\t\tfloat s = computeShadow(vPositionFromLight, shadowSampler, shadowParams.x);\n\t\tcolor *= vec4(s, s, s, 1.);\n\t#endif\n\n\tcolor.rgb *= max(max(0., -vNormal.y * 0.4), dot(vNormal, normalize(vec3(.2, 1., .1)) * 1.) + 0.4);\n\t//color.rgb *= max(0., dot(vNormal, normalize(vec3(-.2, 1., -.1))) + 0.4);\n\n\t#ifdef FLASH\n\t\tcolor.rgb += emissiveColor;\n\t#endif\n\n\tfloat fog = calcFogFactor();\n\tcolor.rgb = fog * color.rgb + (1.0 - fog) * vFogColor;\n\n\t#ifdef EGGSHELL\n\t\tfloat f = step(dot(vNormal, vPositionFromCamera), 0.4);\n\t\tcolor.rgb = mix(color.rgb, outlineColor.rgb, f * outlineColor.a);\n\t#endif\n\n\tgl_FragColor = color;\n}\n";
    var spatialSoundOpts = {
        spatialSound: true,
        distanceModel: "exponential",
        rolloffFactor: 1
    };
    function SoundPool(url, scene, poolSize, callback) {
        var sound = new BABYLON.Sound("", url, scene, callback, spatialSoundOpts);
        this.pool = [ sound ];
        for (var i = 1; i < poolSize; i++) {
            this.pool.push(sound.clone());
        }
        this.poolSize = poolSize;
    }
    SoundPool.v1 = new BABYLON.Vector3();
    SoundPool.v2 = new BABYLON.Vector3();
    SoundPool.prototype.play = function(origin, isMesh) {
        var sound;
        if (isMesh) {
            SoundPool.v1.copyFrom(origin.absolutePosition);
        } else {
            SoundPool.v1.copyFrom(origin);
        }
        for (var i = 0; i < this.poolSize; i++) {
            if (!this.pool[i].isPlaying) {
                sound = this.pool[i];
                break;
            }
        }
        if (!sound) {
            try {
                var thisDistance = BABYLON.Vector3.Distance(SoundPool.v1, camera.globalPosition);
                var minDistance = 1e7;
            } catch (e) {
                console.log(SoundPool.v1, camera.globalPosition);
            }
            for (var i = 0; i < this.poolSize; i++) {
                var thatDistance = BABYLON.Vector3.Distance(this.pool[i]._position, camera.globalPosition);
                if (thatDistance < minDistance && thisDistance < thatDistance) {
                    sound = this.pool[i];
                    minDistance = thatDistance;
                }
            }
        }
        if (sound) {
            if (isMesh) {
                sound.attachToMesh(origin);
            } else {
                sound.setPosition(SoundPool.v1);
            }
            sound.play();
        }
    };
    "use strict";
    function SpatulaActor(spatula, scene) {
        this.spatula = spatula;
        this.scene = spatula.scene;
        this.mesh = this.scene.cloneMesh("spatula");
        this.mesh.emissiveColor = new BABYLON.Color3(.8, .6, .2);
        this.mesh.setRenderingGroupId(1);
    }
    SpatulaActor.prototype.drop = function() {
        this.mesh.parent = null;
        Sounds.spatula.drop.play();
    };
    SpatulaActor.prototype.update = function(delta) {
        this.mesh.position.x = this.spatula.x;
        this.mesh.position.y = this.spatula.y + .1;
        this.mesh.position.z = this.spatula.z;
        if (this.spatula.controlledBy == 255) {
            this.mesh.rotation.y += .1 * delta;
        } else {
            var player = players[this.spatula.controlledBy];
            if (player) {
                this.mesh.rotation.y = player.yaw;
            }
        }
    };
